import { createRemoteJWKSet, jwtVerify } from "jose";
import { NextResponse } from "next/server";
import { acmAuthIssuer, identityFunctionUrl, oauthClientId, oauthRedirectUri, requiredEnv, runtimeEnv, siteOrigin } from "../../../auth/config";
import { csrfTokenMatches, openValue, safeReturnTo, sealSession } from "../../../auth/session";
import type { OAuthTransaction, ProductSession } from "../../../auth/session";

const TRANSACTION_COOKIE = "mini-golf-oauth";
const SESSION_COOKIE = "mini-golf-session";

function clearCookie(response: NextResponse, name: string) {
  response.cookies.set(name, "", { httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 0 });
}

function failureResponse(returnTo = "/") {
  const safePath = safeReturnTo(returnTo);
  const separator = safePath.includes("?") ? "&" : "?";
  const response = NextResponse.redirect(new URL(`${safePath}${separator}auth_error=connection`, siteOrigin()));
  clearCookie(response, TRANSACTION_COOKIE);
  clearCookie(response, SESSION_COOKIE);
  return response;
}

function validTransaction(value: unknown) {
  if (!value || typeof value !== "object") return false;
  const transaction = value as Record<string, unknown>;
  return ["state", "verifier", "nonce", "returnTo"].every((key) => typeof transaction[key] === "string" && Boolean(transaction[key]))
    && typeof transaction.createdAt === "number";
}

async function exchangeCode(code: string, verifier: string) {
  const clientId = oauthClientId();
  const secret = runtimeEnv("ACM_OAUTH_CLIENT_SECRET");
  const headers = new Headers({ "content-type": "application/x-www-form-urlencoded", accept: "application/json" });
  if (secret) headers.set("authorization", `Basic ${btoa(`${clientId}:${secret}`)}`);
  const response = await fetch(`${acmAuthIssuer()}/oauth/token`, {
    method: "POST",
    headers,
    body: new URLSearchParams({
      grant_type: "authorization_code",
      code,
      client_id: clientId,
      redirect_uri: oauthRedirectUri(),
      code_verifier: verifier,
    }),
  });
  if (!response.ok) return null;
  const result = await response.json() as Record<string, unknown>;
  if (typeof result.access_token !== "string" || typeof result.refresh_token !== "string" || typeof result.id_token !== "string") return null;
  return {
    accessToken: result.access_token,
    refreshToken: result.refresh_token,
    idToken: result.id_token,
    expiresIn: typeof result.expires_in === "number" ? result.expires_in : 3600,
  };
}

async function validateIdToken(idToken: string, nonce: string) {
  const issuer = acmAuthIssuer();
  const jwks = createRemoteJWKSet(new URL(`${issuer}/.well-known/jwks.json`));
  const { payload } = await jwtVerify(idToken, jwks, { issuer, audience: oauthClientId() });
  if (payload.nonce !== nonce || typeof payload.sub !== "string" || payload.email_verified !== true) return null;
  return payload;
}

async function establishProductIdentity(accessToken: string, idToken: string) {
  const response = await fetch(identityFunctionUrl(), {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({ product_key: "mini-golf-scorecard", client_id: oauthClientId(), id_token: idToken }),
  });
  if (!response.ok) return null;
  const identity = await response.json() as Record<string, unknown>;
  if (typeof identity.subject !== "string" || identity.email_verified !== true) return null;
  return identity.subject;
}

export async function GET(request: Request) {
  let returnTo = "/";
  try {
    const requestUrl = new URL(request.url);
    const secret = requiredEnv("MINI_GOLF_SESSION_SECRET");
    const transactionCookie = request.headers.get("cookie")?.match(/(?:^|;\s*)mini-golf-oauth=([^;]+)/)?.[1];
    const stored = await openValue(transactionCookie, secret);
    if (!validTransaction(stored)) return failureResponse();
    const transaction = stored as OAuthTransaction;
    returnTo = transaction.returnTo;
    if (Math.floor(Date.now() / 1000) - transaction.createdAt > 600) return failureResponse(returnTo);

    const code = requestUrl.searchParams.get("code");
    const state = requestUrl.searchParams.get("state");
    if (requestUrl.searchParams.get("error") || !code || !state || !(await csrfTokenMatches(transaction.state, state))) {
      return failureResponse(returnTo);
    }
    const tokens = await exchangeCode(code, transaction.verifier);
    if (!tokens) return failureResponse(returnTo);
    const claims = await validateIdToken(tokens.idToken, transaction.nonce);
    if (!claims) return failureResponse(returnTo);
    const subject = await establishProductIdentity(tokens.accessToken, tokens.idToken);
    if (!subject) return failureResponse(returnTo);

    const now = Math.floor(Date.now() / 1000);
    const session: ProductSession = {
      subject,
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      idToken: tokens.idToken,
      expiresAt: now + Math.min(Math.max(tokens.expiresIn, 60), 3600),
      issuedAt: now,
    };
    const response = NextResponse.redirect(new URL(safeReturnTo(returnTo), siteOrigin()));
    response.cookies.set(SESSION_COOKIE, await sealSession(session, secret), { httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 60 * 60 * 8 });
    clearCookie(response, TRANSACTION_COOKIE);
    return response;
  } catch {
    return failureResponse(returnTo);
  }
}

import { NextResponse } from "next/server";
import { acmAuthIssuer, identityFunctionUrl, oauthClientId, requiredEnv, runtimeEnv } from "../../../auth/config";
import { openSession, ProductSession, sealSession, SESSION_COOKIE, SESSION_REFRESH_WINDOW_SECONDS } from "../../../auth/session";

const NO_STORE = { "cache-control": "no-store" };

function clearSession(response: NextResponse) {
  response.cookies.set(SESSION_COOKIE, "", { httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 0 });
}

async function refreshTokens(session: ProductSession) {
  const clientId = oauthClientId();
  const secret = runtimeEnv("ACM_OAUTH_CLIENT_SECRET");
  const headers = new Headers({ "content-type": "application/x-www-form-urlencoded", accept: "application/json" });
  if (secret) headers.set("authorization", `Basic ${btoa(`${clientId}:${secret}`)}`);
  const response = await fetch(`${acmAuthIssuer()}/oauth/token`, {
    method: "POST",
    headers,
    body: new URLSearchParams({ grant_type: "refresh_token", refresh_token: session.refreshToken, client_id: clientId }),
  });
  if (!response.ok) return null;
  const result = await response.json() as Record<string, unknown>;
  if (typeof result.access_token !== "string" || typeof result.refresh_token !== "string" || typeof result.id_token !== "string") return null;
  return {
    accessToken: result.access_token,
    refreshToken: result.refresh_token,
    idToken: result.id_token,
    expiresIn: typeof result.expires_in === "number" ? result.expires_in : 3600,
  };
}

async function checkIdentity(session: ProductSession) {
  const response = await fetch(identityFunctionUrl(), {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${session.accessToken}` },
    body: JSON.stringify({ product_key: "mini-golf-scorecard", client_id: oauthClientId(), id_token: session.idToken }),
  });
  if (!response.ok) return null;
  const identity = await response.json() as Record<string, unknown>;
  return typeof identity.subject === "string" && identity.email_verified === true ? identity.subject : null;
}

export async function GET(request: Request) {
  const response = NextResponse.json({ authenticated: false }, { headers: NO_STORE });
  try {
    const value = request.headers.get("cookie")?.match(/(?:^|;\s*)mini-golf-session=([^;]+)/)?.[1];
    const secret = requiredEnv("MINI_GOLF_SESSION_SECRET");
    const now = Math.floor(Date.now() / 1000);
    const session = await openSession(value, secret, now, true);
    if (!session || now - session.issuedAt > 60 * 60 * 8) {
      clearSession(response);
      return response;
    }

    let current = session;
    let changed = false;
    if (session.expiresAt <= now + SESSION_REFRESH_WINDOW_SECONDS) {
      const refreshed = await refreshTokens(session);
      if (!refreshed) {
        clearSession(response);
        return response;
      }
      current = { ...session, accessToken: refreshed.accessToken, refreshToken: refreshed.refreshToken, idToken: refreshed.idToken, expiresAt: now + Math.min(Math.max(refreshed.expiresIn, 60), 3600) };
      changed = true;
    }

    const subject = await checkIdentity(current);
    if (!subject || subject !== current.subject) {
      clearSession(response);
      return response;
    }
    const authenticated = NextResponse.json({ authenticated: true }, { headers: NO_STORE });
    if (changed) authenticated.cookies.set(SESSION_COOKIE, await sealSession(current, secret), { httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 60 * 60 * 8 });
    return authenticated;
  } catch {
    clearSession(response);
    return response;
  }
}

import { NextResponse } from "next/server";
import { siteOrigin } from "../../../auth/config";
import { SESSION_COOKIE } from "../../../auth/session";

export async function POST(request: Request) {
  const origin = request.headers.get("origin");
  if (origin && origin !== siteOrigin()) return NextResponse.json({ error: "Invalid request origin." }, { status: 403, headers: { "cache-control": "no-store" } });
  const response = NextResponse.json({ status: "signed_out" }, { headers: { "cache-control": "no-store" } });
  response.cookies.set(SESSION_COOKIE, "", { httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 0 });
  return response;
}

import { NextResponse } from "next/server";
import { acmAuthIssuer, oauthClientId, oauthRedirectUri, requiredEnv, siteOrigin } from "../../../auth/config";
import { OAuthTransaction, pkceChallenge, randomToken, safeReturnTo, sealValue } from "../../../auth/session";

const TRANSACTION_COOKIE = "mini-golf-oauth";
const TRANSACTION_MAX_AGE_SECONDS = 600;

export async function GET(request: Request) {
  try {
    const requestUrl = new URL(request.url);
    const transaction: OAuthTransaction = {
      state: randomToken(),
      verifier: randomToken(48),
      nonce: randomToken(),
      returnTo: safeReturnTo(requestUrl.searchParams.get("return_to")),
      createdAt: Math.floor(Date.now() / 1000),
    };
    const authorizeUrl = new URL(`${acmAuthIssuer()}/oauth/authorize`);
    authorizeUrl.search = new URLSearchParams({
      response_type: "code",
      client_id: oauthClientId(),
      redirect_uri: oauthRedirectUri(),
      scope: "openid email",
      state: transaction.state,
      nonce: transaction.nonce,
      code_challenge: await pkceChallenge(transaction.verifier),
      code_challenge_method: "S256",
    }).toString();
    const response = NextResponse.redirect(authorizeUrl);
    response.cookies.set(TRANSACTION_COOKIE, await sealValue(transaction, requiredEnv("MINI_GOLF_SESSION_SECRET")), {
      httpOnly: true,
      secure: true,
      sameSite: "lax",
      path: "/",
      maxAge: TRANSACTION_MAX_AGE_SECONDS,
    });
    return response;
  } catch {
    return NextResponse.redirect(new URL("/?auth_error=configuration", siteOrigin()));
  }
}

import { env as workerEnv } from "cloudflare:workers";

export function runtimeEnv(name: string) {
  const processValue = typeof process !== "undefined" ? process.env[name] : undefined;
  const workerValue = (workerEnv as Record<string, unknown> | undefined)?.[name];
  return String(processValue ?? workerValue ?? "").trim();
}

export function requiredEnv(name: string) {
  const value = runtimeEnv(name);
  if (!value) throw new Error(`${name} is not configured`);
  return value;
}

export function identityFunctionUrl() {
  return requiredEnv("ACM_IDENTITY_FUNCTION_URL");
}

export function acmAuthIssuer() {
  return requiredEnv("ACM_AUTH_ISSUER");
}

export function oauthRedirectUri() {
  return requiredEnv("ACM_OAUTH_REDIRECT_URI");
}

export function oauthClientId() {
  return requiredEnv("ACM_OAUTH_CLIENT_ID");
}

export function siteOrigin() {
  return new URL(requiredEnv("MINI_GOLF_SITE_URL")).origin;
}

import { compactDecrypt, CompactEncrypt } from "jose";

export const SESSION_COOKIE = "mini-golf-session";
export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 8;
export const SESSION_REFRESH_WINDOW_SECONDS = 60 * 15;

export type ProductSession = {
  subject: string;
  accessToken: string;
  refreshToken: string;
  idToken: string;
  expiresAt: number;
  issuedAt: number;
};

export type OAuthTransaction = {
  state: string;
  verifier: string;
  nonce: string;
  returnTo: string;
  createdAt: number;
};

async function sessionKey(secret: string) {
  if (!secret || secret.length < 32) throw new Error("MINI_GOLF_SESSION_SECRET is not configured");
  return new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(secret)));
}

export async function sealSession(session: ProductSession, secret: string) {
  return sealValue(session, secret);
}

export async function sealValue(value: unknown, secret: string) {
  return new CompactEncrypt(new TextEncoder().encode(JSON.stringify(value)))
    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
    .encrypt(await sessionKey(secret));
}

export async function openSession(value: string | undefined, secret: string, now = Math.floor(Date.now() / 1000), allowExpired = false) {
  const parsed = await openValue(value, secret);
  if (!parsed || typeof parsed !== "object") return null;
  const session = parsed as Partial<ProductSession>;
  if (
    typeof session.subject !== "string" || !session.subject ||
    typeof session.accessToken !== "string" || !session.accessToken ||
    typeof session.refreshToken !== "string" || !session.refreshToken ||
    typeof session.idToken !== "string" || !session.idToken ||
    typeof session.expiresAt !== "number" || (!allowExpired && session.expiresAt <= now) ||
    typeof session.issuedAt !== "number" || now - session.issuedAt > SESSION_MAX_AGE_SECONDS
  ) return null;
  return session as ProductSession;
}

export async function openValue(value: string | undefined, secret: string) {
  if (!value) return null;
  try {
    const { plaintext } = await compactDecrypt(value, await sessionKey(secret));
    const text = new TextDecoder().decode(plaintext);
    return JSON.parse(text) as unknown;
  } catch {
    return null;
  }
}

export function safeReturnTo(value: string | null | undefined) {
  if (!value || !value.startsWith("/") || value.startsWith("//")) return "/";
  try {
    const url = new URL(value, "https://mini-golf.local");
    if (url.origin !== "https://mini-golf.local" || url.pathname.startsWith("/api/auth")) return "/";
    return `${url.pathname}${url.search}${url.hash}`;
  } catch {
    return "/";
  }
}

export async function csrfTokenMatches(expected: string | undefined, received: string | null) {
  if (!expected || !received) return false;
  const [left, right] = await Promise.all([
    crypto.subtle.digest("SHA-256", new TextEncoder().encode(expected)),
    crypto.subtle.digest("SHA-256", new TextEncoder().encode(received)),
  ]);
  return new Uint8Array(left).every((value, index) => value === new Uint8Array(right)[index]);
}

export function randomToken(bytes = 32) {
  const values = new Uint8Array(bytes);
  crypto.getRandomValues(values);
  return btoa(String.fromCharCode(...values))
    .replaceAll("+", "-")
    .replaceAll("/", "_")
    .replaceAll("=", "");
}

export async function pkceChallenge(verifier: string) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
  const values = new Uint8Array(digest);
  return btoa(String.fromCharCode(...values))
    .replaceAll("+", "-")
    .replaceAll("/", "_")
    .replaceAll("=", "");
}

import type { Game } from "../types";

type GameSetupProps = {
  game: Game;
  onHolesChange: (holes: number) => void;
  onPlayersChange: (players: number) => void;
  onReset: () => void;
  onNewGame: () => void;
};

export function GameSetup({
  game,
  onHolesChange,
  onPlayersChange,
  onReset,
  onNewGame,
}: GameSetupProps) {
  const handleNewGame = () => {
    if (confirm("Start a new game? Your current scorecard will be cleared.")) {
      onNewGame();
    }
  };

  return (
    <section className="panel setup">
      <div className="field">
        <label htmlFor="holes">Course holes</label>
        <select id="holes" value={game.holes} onChange={(event) => onHolesChange(Number(event.target.value))}>
          {Array.from({ length: 18 }, (_, index) => (
            <option key={index + 1} value={index + 1}>
              {index + 1} {index ? "holes" : "hole"}
            </option>
          ))}
        </select>
      </div>
      <div className="field">
        <label htmlFor="players">Players</label>
        <select id="players" value={game.players.length} onChange={(event) => onPlayersChange(Number(event.target.value))}>
          {Array.from({ length: 8 }, (_, index) => (
            <option key={index + 1} value={index + 1}>
              {index + 1} {index ? "players" : "player"}
            </option>
          ))}
        </select>
      </div>
      <div className="setup-actions">
        <button className="button secondary" onClick={onReset}>Reset scores</button>
        <button className="button ghost" onClick={handleNewGame}>New game</button>
      </div>
    </section>
  );
}

import type { PlayerStats } from "../types";
import { formatStat } from "../domain/scorecard";

type LeaderboardProps = {
  stats: PlayerStats[];
  holes: number;
};

export function Leaderboard({ stats, holes }: LeaderboardProps) {
  const leader = stats.find((stat) => stat.values.length);

  return (
    <section className="summary-grid">
      {stats.map((stat) => (
        <article
          className={`summary-card ${leader?.id === stat.id ? "leader" : ""}`}
          key={stat.id}

        >
          <div className="card-top">
            <h3>
              {stat.name || "Unnamed player"}
            </h3>
            {leader?.id === stat.id && <span className="leader-badge">Leading</span>}
          </div>
          <div className="big-score">{stat.values.length ? stat.total : "—"}<span>strokes</span></div>
          <dl>
            <div><dt>Average</dt><dd>{formatStat(stat.average)}</dd></div>
            <div><dt>Std deviation</dt><dd>{formatStat(stat.deviation)}</dd></div>
            <div><dt>Holes played</dt><dd>{stat.values.length} / {holes}</dd></div>
          </dl>
        </article>
      ))}
    </section>
  );
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  getHoleResultClass,
  isHoleComplete,
  parseScore,
  MAX_SCORE,
} from "../domain/scorecard";
import { DEFAULT_COLUMN_WIDTH, MIN_COLUMN_WIDTH } from "../domain/player-layout";
import type { ColumnSizingLayout } from "../hooks/use-column-sizing";
import type { PlayerReorderingLayout } from "../hooks/use-player-reordering";
import type { Game, ScorecardExportModel, TextSize } from "../types";

const TABLE_SIZES: Record<TextSize, string> = {
  small: "13px",
  medium: "16px",
  large: "19px",
};

function moveMobileScoreCaretToEnd(input: HTMLInputElement) {
  if (!input.value || !window.matchMedia("(max-width: 650px), (hover: none) and (pointer: coarse)").matches) return;

  // Run after the browser places the caret for the tap, including repeat taps.
  requestAnimationFrame(() => {
    if (document.activeElement === input) {
      input.setSelectionRange(input.value.length, input.value.length);
    }
  });
}

type ScoreTableProps = {
  game: Game;
  exportModel: ScorecardExportModel;
  tableSize: TextSize;
  layout: PlayerReorderingLayout & ColumnSizingLayout;
  onTableSizeChange: (size: TextSize) => void;
  onAutoResize: () => void;
  onScore: (playerId: string, hole: number, value: string) => void;
  onAdjustScore: (playerId: string, hole: number, delta: number) => void;
  onPlayerNameChange: (playerId: string, name: string) => void;
  onMovePlayer: (playerId: string, direction: -1 | 1) => void;
};

export function ScoreTable({
  game,
  exportModel,
  tableSize,
  layout,
  onTableSizeChange,
  onAutoResize,
  onScore,
  onAdjustScore,
  onPlayerNameChange,
  onMovePlayer,
}: ScoreTableProps) {
  const [scoreError, setScoreError] = useState<{ playerId: string; hole: number; game: Game } | null>(null);
  const [moveAnnouncement, setMoveAnnouncement] = useState("");
  const movedControl = useRef<{ playerId: string; direction: -1 | 1 } | null>(null);

  useLayoutEffect(() => {
    const moved = movedControl.current;
    if (!moved) return;
    movedControl.current = null;
    const preferred = document.getElementById(`move-${moved.playerId}-${moved.direction}`) as HTMLButtonElement | null;
    const alternative = document.getElementById(`move-${moved.playerId}-${-moved.direction}`) as HTMLButtonElement | null;
    const target = preferred && !preferred.disabled ? preferred : alternative && !alternative.disabled ? alternative : document.getElementById(`name-${moved.playerId}`);
    target?.focus();
  }, [game.players]);

  function movePlayer(playerId: string, direction: -1 | 1) {
    const index = game.players.findIndex(player => player.id === playerId);
    const next = index + direction;
    if (index < 0 || next < 0 || next >= game.players.length) return;
    movedControl.current = { playerId, direction };
    onMovePlayer(playerId, direction);
    setMoveAnnouncement(`${game.players[index].name || "Unnamed player"} moved to position ${next + 1} of ${game.players.length}.`);
  }

  function enterScore(playerId: string, hole: number, value: string) {
    if (parseScore(value) === null) { setScoreError({ playerId, hole, game }); return; }
    setScoreError(null);
    onScore(playerId, hole, value);
  }

  const activeScoreError = scoreError?.game === game ? scoreError : null;
  const completedHoles = Array.from({ length: game.holes }, (_, hole) =>
    isHoleComplete(game, hole),
  );
  useEffect(() => {
    const active = document.activeElement;
    if (active instanceof HTMLInputElement && active.classList.contains("score-input")) {
      requestAnimationFrame(() => active.setSelectionRange(active.value.length, active.value.length));
    }
  }, [game]);

  return (
    <section className="panel score-panel">
      <div className="section-heading">
        <div><h2>Enter your scores</h2></div>
        <div className="heading-actions">
          <span className="progress">{completedHoles.filter(Boolean).length} / {game.holes} holes complete</span>
          <label className="table-size-control" htmlFor="table-size">
            Table text
            <select id="table-size" value={tableSize} onChange={(event) => onTableSizeChange(event.target.value as TextSize)}>
              <option value="small">Small</option>
              <option value="medium">Standard</option>
              <option value="large">Large</option>
            </select>
          </label>
          <button className="button compact-toggle" onClick={onAutoResize}>↔ Auto-resize columns</button>
        </div>
      </div>
      <p className="sr-only" role="status">{moveAnnouncement}</p>
      <p id="score-entry-error" className="score-entry-error" role="alert">{activeScoreError ? `Enter a whole-number score from 1 to ${MAX_SCORE.toLocaleString("en-GB")}, or clear the score. The previous score has been kept.` : ""}</p>
      <div className="table-wrap">
        <table className={game.players.length === 2 ? "two-player-table" : ""} style={{ fontSize: TABLE_SIZES[tableSize] }}>
          <colgroup>
            <col className="hole-col" />
            {game.players.map((player) => (
              <col key={player.id} style={{ width: `${layout.widths[player.id] ?? DEFAULT_COLUMN_WIDTH}px` }} />
            ))}
            <col className="total-col" />
          </colgroup>
          <thead>
            <tr>
              <th>Hole</th>
              {game.players.map((player, index) => (
                <th
                  key={player.id}
                  ref={(element) => layout.registerHeader(player.id, element)}
                  onDragOver={(event) => layout.handleHeaderDragOver(event, player.id)}
                  onDrop={() => layout.dropPlayer(player.id, layout.dropSide === "after")}
                  className={`${layout.dragging === player.id ? "dragging" : ""} ${layout.dropTarget === player.id && layout.dragging !== player.id ? `drop-target ${layout.dropSide}` : ""}`}
                >
                  <span
                    className="drag-handle"
                    onPointerDown={(event) => layout.pointerDrag(event, player.id)}
                    draggable
                    onDragStart={() => layout.startDragging(player.id)}
                    onDragEnd={layout.clearDragging}
                    aria-label={`Drag ${player.name}`}
                  >
                    ⠿
                  </span>
                  <label className="sr-only" htmlFor={`name-${player.id}`}>Player name</label>
                  <input ref={index === 0 ? layout.registerNameInput : undefined} id={`name-${player.id}`} className="name-input" value={player.name} onChange={(event) => onPlayerNameChange(player.id, event.target.value)} />
                  <span className="player-move">
                    <button id={`move-${player.id}--1`} type="button" aria-label={`Move ${player.name} left`} disabled={index === 0} onClick={() => movePlayer(player.id, -1)}>‹</button>
                    <button id={`move-${player.id}-1`} type="button" aria-label={`Move ${player.name} right`} disabled={index === game.players.length - 1} onClick={() => movePlayer(player.id, 1)}>›</button>
                  </span>
                  {/* eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions, jsx-a11y/no-noninteractive-tabindex -- A focusable adjustable separator exposes column width and keyboard resizing. */}
                  <span className="resize-handle" role="separator" tabIndex={0} aria-orientation="vertical"
                    aria-valuemin={MIN_COLUMN_WIDTH} aria-valuemax={Number.MAX_SAFE_INTEGER} aria-valuenow={layout.widths[player.id] ?? DEFAULT_COLUMN_WIDTH}
                    aria-valuetext={`${layout.widths[player.id] ?? DEFAULT_COLUMN_WIDTH} pixels`}
                    onPointerDown={(event) => layout.resizeColumn(event, player.id)}
                    onKeyDown={(event) => {
                      if (!["ArrowLeft", "ArrowRight", "Home"].includes(event.key)) return;
                      event.preventDefault(); event.stopPropagation();
                      layout.resizeColumnBy(player.id, event.key === "Home" ? "minimum" : event.key === "ArrowLeft" ? -10 : 10);
                    }} aria-label={`Resize ${player.name} column`} />
                </th>
              ))}
              <th>Total</th>
            </tr>
          </thead>
          <tbody>
            {Array.from({ length: game.holes }, (_, hole) => (
              <tr key={hole}>
                <th>
                  <span className="hole-number">{hole + 1}</span>
                  {completedHoles[hole] && <span className="tick" aria-label="Complete">✓</span>}
                </th>
                {game.players.map((player) => (
                  <td key={player.id} className={getHoleResultClass(game, hole, player.id)}>
                    <label className="sr-only" htmlFor={`${player.id}-${hole}`}>{player.name}, hole {hole + 1}</label>
                    <span className="score-control">
                      <input
                        id={`${player.id}-${hole}`}
                        className="score-input"
                        inputMode="numeric"
                        type="tel"
                        value={game.scores[player.id]?.[hole] ?? ""}
                        onFocus={(event) => moveMobileScoreCaretToEnd(event.currentTarget)}
                        onClick={(event) => moveMobileScoreCaretToEnd(event.currentTarget)}
                        aria-invalid={activeScoreError?.playerId === player.id && activeScoreError.hole === hole}
                        aria-describedby={activeScoreError?.playerId === player.id && activeScoreError.hole === hole ? "score-entry-error" : undefined}
                        onChange={(event) => enterScore(player.id, hole, event.target.value)}
                      />
                      <span className="score-stepper">
                        <button type="button" aria-label={`Increase ${player.name}, hole ${hole + 1}`} disabled={parseScore(game.scores[player.id]?.[hole]) === MAX_SCORE} onMouseDown={(event) => event.preventDefault()} onClick={() => { setScoreError(null); onAdjustScore(player.id, hole, 1); }}>▲</button>
                        <button type="button" aria-label={`Decrease ${player.name}, hole ${hole + 1}`} onMouseDown={(event) => event.preventDefault()} onClick={() => { setScoreError(null); onAdjustScore(player.id, hole, -1); }}>▼</button>
                      </span>
                    </span>
                  </td>
                ))}
                <td className="hole-total">{exportModel.holeTotals[hole] || "—"}</td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <th>Total</th>
              {exportModel.playerTotals.map((total, index) => <td key={game.players[index].id}>{total || "—"}</td>)}
              <td>{exportModel.grandTotal || "—"}</td>
            </tr>
          </tfoot>
        </table>
      </div>
    </section>
  );
}

