import type { Player } from "../types";

export const DEFAULT_COLUMN_WIDTH = 120;
export const MIN_COLUMN_WIDTH = 68;
export const AUTO_COLUMN_MIN_WIDTH = 90;
export const AUTO_COLUMN_PADDING = 44;

export type PlayerHeaderBounds = {
  id: string;
  left: number;
  right: number;
};

export type DropPosition = {
  targetId: string;
  after: boolean;
} | null;

export function resizeColumnWidth(
  initialWidth: number,
  delta: number,
  minimum = MIN_COLUMN_WIDTH,
): number {
  return Math.max(minimum, initialWidth + delta);
}

export function getAutomaticColumnWidth(
  players: Player[],
  measureText: (value: string) => number,
  minimum = AUTO_COLUMN_MIN_WIDTH,
  padding = AUTO_COLUMN_PADDING,
): number {
  return Math.max(
    minimum,
    ...players.map((player) =>
      Math.ceil(measureText(player.name || "Player") + padding),
    ),
  );
}

export function getDropPosition(
  headers: PlayerHeaderBounds[],
  draggingId: string,
  clientX: number,
): DropPosition {
  const fromIndex = headers.findIndex((header) => header.id === draggingId);
  if (fromIndex < 0) return null;

  let targetIndex = -1;
  let after = false;

  for (let index = fromIndex + 1; index < headers.length; index += 1) {
    if (clientX >= headers[index].right) {
      targetIndex = index;
      after = true;
    }
  }

  for (let index = fromIndex - 1; index >= 0; index -= 1) {
    if (clientX <= headers[index].left) {
      targetIndex = index;
      after = false;
    }
  }

  if (
    headers.length &&
    clientX >= headers[headers.length - 1].right &&
    fromIndex < headers.length - 1
  ) {
    targetIndex = headers.length - 1;
    after = true;
  }

  if (headers.length && clientX <= headers[0].left && fromIndex > 0) {
    targetIndex = 0;
    after = false;
  }

  if (targetIndex < 0 || targetIndex === fromIndex) return null;
  return { targetId: headers[targetIndex].id, after };
}

import type {
  Game,
  Player,
  PlayerStats,
  ScorecardExportModel,
} from "../types";

export const DEFAULT_HOLES = 9;
export const MAX_HOLES = 18;
export const DEFAULT_PLAYERS = 2;
export const MAX_PLAYERS = 8;

// Keep every possible round total within exact JavaScript integer arithmetic,
// including after resizing to the largest supported course and player count.
export const MAX_SCORE = Math.floor(Number.MAX_SAFE_INTEGER / (MAX_PLAYERS * MAX_HOLES));

/** Empty is an unplayed hole (zero); null is invalid input. Preserve raw spelling. */
export function parseScore(value: unknown): number | null {
  if (value === "") return 0;
  if (typeof value !== "string" || !/^[0-9]+$/.test(value)) return null;
  const score = Number(value);
  return Number.isSafeInteger(score) && score > 0 && score <= MAX_SCORE ? score : null;
}

export type IdFactory = () => string;

const createId: IdFactory = () =>
  typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2, 10);

const clamp = (value: number, minimum: number, maximum: number) =>
  Math.min(maximum, Math.max(minimum, Math.round(value)));

const emptyScores = (holes: number) => Array.from({ length: holes }, () => "");

export function createGame(
  holes = DEFAULT_HOLES,
  playerCount = DEFAULT_PLAYERS,
  idFactory: IdFactory = createId,
): Game {
  const safeHoles = clamp(holes, 1, MAX_HOLES);
  const safePlayerCount = clamp(playerCount, 1, MAX_PLAYERS);
  const players = Array.from({ length: safePlayerCount }, (_, index) => ({
    id: idFactory(),
    name: `Player ${index + 1}`,
  }));

  return {
    holes: safeHoles,
    players,
    scores: Object.fromEntries(
      players.map((player) => [player.id, emptyScores(safeHoles)]),
    ),
  };
}

export function resizeHoles(game: Game, holes: number): Game {
  const safeHoles = clamp(holes, 1, MAX_HOLES);
  return {
    ...game,
    holes: safeHoles,
    scores: Object.fromEntries(
      game.players.map((player) => [
        player.id,
        Array.from(
          { length: safeHoles },
          (_, hole) => game.scores[player.id]?.[hole] ?? "",
        ),
      ]),
    ),
  };
}

export function resizePlayers(
  game: Game,
  playerCount: number,
  idFactory: IdFactory = createId,
): Game {
  const safePlayerCount = clamp(playerCount, 1, MAX_PLAYERS);
  const players = Array.from({ length: safePlayerCount }, (_, index) =>
    game.players[index] ?? { id: idFactory(), name: `Player ${index + 1}` },
  );

  return {
    ...game,
    players,
    scores: Object.fromEntries(
      players.map((player) => [
        player.id,
        Array.from(
          { length: game.holes },
          (_, hole) => game.scores[player.id]?.[hole] ?? "",
        ),
      ]),
    ),
  };
}

export function setScore(game: Game, playerId: string, hole: number, value: string): Game {
  const playerScores = game.scores[playerId];
  if (!playerScores || !Number.isInteger(hole) || hole < 0 || hole >= game.holes || parseScore(value) === null) return game;

  return {
    ...game,
    scores: {
      ...game.scores,
      [playerId]: playerScores.map((score, index) =>
        index === hole ? value : score,
      ),
    },
  };
}

export function adjustScore(
  game: Game,
  playerId: string,
  hole: number,
  delta: number,
): Game {
  const current = parseScore(game.scores[playerId]?.[hole]);
  if (current === null || (delta !== -1 && delta !== 1)) return game;
  const next = current + delta;
  return setScore(game, playerId, hole, next > 0 ? String(next) : "");
}

export function renamePlayer(game: Game, playerId: string, name: string): Game {
  return {
    ...game,
    players: game.players.map((player) =>
      player.id === playerId ? { ...player, name } : player,
    ),
  };
}

export function resetScores(game: Game): Game {
  return {
    ...game,
    scores: Object.fromEntries(
      game.players.map((player) => [player.id, emptyScores(game.holes)]),
    ),
  };
}

export function reorderPlayers(
  game: Game,
  fromId: string,
  toId: string,
  after = false,
): Game {
  const fromIndex = game.players.findIndex((player) => player.id === fromId);
  if (fromIndex < 0) return game;

  const players = [...game.players];
  const [moved] = players.splice(fromIndex, 1);
  const toIndex = players.findIndex((player) => player.id === toId);
  if (!moved || toIndex < 0) return game;

  players.splice(toIndex + (after ? 1 : 0), 0, moved);
  return { ...game, players };
}

export function movePlayer(game: Game, playerId: string, direction: -1 | 1): Game {
  const index = game.players.findIndex((player) => player.id === playerId);
  const nextIndex = index + direction;
  if (index < 0 || nextIndex < 0 || nextIndex >= game.players.length) return game;

  const players = [...game.players];
  [players[index], players[nextIndex]] = [players[nextIndex], players[index]];
  return { ...game, players };
}

export function numericScores(scores: string[]): number[] {
  return scores
    .map(parseScore)
    .filter((score): score is number => score !== null && score > 0);
}

export function average(values: number[]): number {
  return values.length
    ? values.reduce((sum, value) => sum + value, 0) / values.length
    : 0;
}

export function populationStandardDeviation(values: number[]): number {
  if (!values.length) return 0;
  const mean = average(values);
  return Math.sqrt(
    values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / values.length,
  );
}

export function formatStat(value: number): string {
  return value ? value.toFixed(2) : "—";
}

export function getPlayerStats(game: Game): PlayerStats[] {
  return game.players
    .map((player) => {
      const values = numericScores(game.scores[player.id] ?? []);
      return {
        ...player,
        values,
        total: values.reduce((sum, value) => sum + value, 0),
        average: average(values),
        deviation: populationStandardDeviation(values),
      };
    })
    .sort((first, second) => {
      if (Boolean(first.values.length) !== Boolean(second.values.length)) {
        return first.values.length ? -1 : 1;
      }

      const totalOrder = first.total - second.total;
      if (totalOrder) return totalOrder;

      const firstName = (first.name || "Unnamed player").trim().toLowerCase();
      const secondName = (second.name || "Unnamed player").trim().toLowerCase();
      return firstName < secondName ? -1 : firstName > secondName ? 1 : 0;
    });
}

export function getPlayerTotal(game: Game, playerId: string): number {
  return (game.scores[playerId] ?? []).reduce(
    (sum, score) => sum + (parseScore(score) ?? 0),
    0,
  );
}

export function getPlayerTotals(game: Game): number[] {
  return game.players.map((player) => getPlayerTotal(game, player.id));
}

export function getHoleTotal(game: Game, hole: number): number {
  return game.players.reduce(
    (sum, player) => sum + (parseScore(game.scores[player.id]?.[hole]) ?? 0),
    0,
  );
}

export function getHoleTotals(game: Game): number[] {
  return Array.from({ length: game.holes }, (_, hole) => getHoleTotal(game, hole));
}

export function isHoleComplete(game: Game, hole: number): boolean {
  return game.players.every((player) => (parseScore(game.scores[player.id]?.[hole]) ?? 0) > 0);
}

export function getHoleWinners(game: Game, hole: number): string[] {
  const values = game.players
    .map((player) => ({
      id: player.id,
      score: (parseScore(game.scores[player.id]?.[hole]) ?? 0),
    }))
    .filter((item) => item.score > 0);
  if (!values.length) return [];

  const best = Math.min(...values.map((item) => item.score));
  return values.filter((item) => item.score === best).map((item) => item.id);
}

export function getHoleResultClass(
  game: Game,
  hole: number,
  playerId: string,
): "hole-winner" | "hole-tie" | "" {
  const winners = getHoleWinners(game, hole);
  if (!winners.includes(playerId)) return "";
  return winners.length > 1 ? "hole-tie" : "hole-winner";
}

export function buildExportModel(game: Game): ScorecardExportModel {
  const stats = getPlayerStats(game);
  const playerTotals = getPlayerTotals(game);
  const holeTotals = getHoleTotals(game);

  return {
    game,
    stats,
    playerTotals,
    holeTotals,
    grandTotal: playerTotals.reduce((sum, total) => sum + total, 0),
  };
}

