export async function copyScorecardHtml(model: ScorecardExportModel): Promise<void> {
  if (!navigator.clipboard?.write || typeof ClipboardItem === "undefined") {
    throw new Error("HTML copying is not supported in this browser.");
  }

  const { html, plain } = scorecardToHtml(model);
  await navigator.clipboard.write([new ClipboardItem({
    "text/html": new Blob([html], { type: "text/html" }),
    "text/plain": new Blob([plain], { type: "text/plain" }),
  })]);
}

import type { ScorecardExportModel } from "../types";
import { scorecardToSvg } from "./image.ts";

const loadImage = (url: string) => new Promise<HTMLImageElement>((resolve, reject) => {
  const image = new Image();
  image.onload = () => resolve(image);
  image.onerror = reject;
  image.src = url;
});

const canvasBlob = (canvas: HTMLCanvasElement) => new Promise<Blob>((resolve, reject) => {
  canvas.toBlob((blob) => blob ? resolve(blob) : reject(new Error("Could not create screenshot image.")), "image/png");
});

export async function copyScorecardImage(model: ScorecardExportModel): Promise<void> {
  if (!navigator.clipboard?.write || typeof ClipboardItem === "undefined") {
    throw new Error("Image copying is not supported in this browser.");
  }

  const { svg, width, height } = scorecardToSvg(model);
  const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" }));
  try {
    const image = await loadImage(url);
    const canvas = document.createElement("canvas");
    const outputScale = 4;
    canvas.width = width * outputScale;
    canvas.height = height * outputScale;
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Could not prepare screenshot image.");
    context.scale(outputScale, outputScale);
    context.drawImage(image, 0, 0);
    await navigator.clipboard.write([new ClipboardItem({ "image/png": await canvasBlob(canvas) })]);
  } finally {
    URL.revokeObjectURL(url);
  }
}

import type { ScorecardExportModel } from "../types";
