function spreadsheetSafeCell(value: string): string {
  // Quote escaping alone does not prevent a spreadsheet interpreting a cell
  // as a formula. Keep this protection local to CSV, before CSV quoting.
  const firstCharacter = value.charCodeAt(0);
  return firstCharacter <= 31 || firstCharacter === 127 || /^[\s=+@-]/.test(value)
    ? `'${value}` : value;
}

export function scorecardToCsv(model: ScorecardExportModel): string {
  const prepared = prepareScorecardExport(model);
  const rows: string[][] = [["Hole", ...prepared.playerNames, "Total"]];

  prepared.scoreRows.forEach((row) => {
    rows.push([
      String(row.hole),
      ...row.scores,
      displayTotal(row.total),
    ]);
  });

  rows.push(["Total", ...prepared.playerTotals.map(displayTotal), displayTotal(prepared.grandTotal)]);
  rows.push([], ["Leaderboard"], ["Rank", "Player", "Total", "Average", "Std Deviation", "Holes Played"]);
  prepared.leaderboardRows.forEach((stat) => {
    rows.push([
      String(stat.rank),
      stat.name,
      String(stat.values.length ? stat.total : "—"),
      formatExportStat(stat.average, stat.values.length > 0),
      formatExportStat(stat.deviation, stat.values.length > 0),
      `${stat.values.length} / ${prepared.game.holes}`,
    ]);
  });

  return rows
    .map((row) => row.map((cell) => `"${spreadsheetSafeCell(String(cell)).replaceAll('"', '""')}"`).join(","))
    .join("\n");
}

import type { ScorecardExportModel } from "../types";
import { scorecardToCsv } from "./csv.ts";

export type CsvDownloadEnvironment = {
  createObjectURL: (blob: Blob) => string;
  revokeObjectURL: (url: string) => void;
  createAnchor: () => HTMLAnchorElement;
};

function browserEnvironment(): CsvDownloadEnvironment {
  return {
    createObjectURL: (blob) => URL.createObjectURL(blob),
    revokeObjectURL: (url) => URL.revokeObjectURL(url),
    createAnchor: () => document.createElement("a"),
  };
}

export function downloadScorecardCsv(
  model: ScorecardExportModel,
  environment: CsvDownloadEnvironment = browserEnvironment(),
): void {
  const url = environment.createObjectURL(
    new Blob([scorecardToCsv(model)], { type: "text/csv;charset=utf-8" }),
  );
  const anchor = environment.createAnchor();
  anchor.href = url;
  anchor.download = "mini-golf-scorecard.csv";
  anchor.click();
  environment.revokeObjectURL(url);
}

import type { PlayerStats, ScorecardExportModel } from "../types";

export type PreparedScoreRow = {
  hole: number;
  scores: string[];
  total: number;
};

export type PreparedLeaderboardRow = PlayerStats & {
  rank: number;
};

export type PreparedScorecardExport = {
  game: ScorecardExportModel["game"];
  playerNames: string[];
  scoreRows: PreparedScoreRow[];
  leaderboardRows: PreparedLeaderboardRow[];
  playerTotals: number[];
  holeTotals: number[];
  grandTotal: number;
};

export function prepareScorecardExport(
  model: ScorecardExportModel,
): PreparedScorecardExport {
  const { game, stats, playerTotals, holeTotals, grandTotal } = model;

  return {
    game,
    playerNames: game.players.map((player) => player.name),
    scoreRows: Array.from({ length: game.holes }, (_, hole) => ({
      hole: hole + 1,
      scores: game.players.map((player) => game.scores[player.id]?.[hole] ?? ""),
      total: holeTotals[hole] ?? 0,
    })),
    leaderboardRows: stats.map((stat, index) => ({ ...stat, rank: index + 1 })),
    playerTotals: [...playerTotals],
    holeTotals: [...holeTotals],
    grandTotal,
  };
}

export function displayScore(value: string): string {
  return value || "—";
}

export function displayTotal(value: number): string {
  return value ? String(value) : "—";
}

export function formatExportStat(value: number, hasValues = value !== 0): string {
  return hasValues ? value.toFixed(2) : "—";
}

import type { ScorecardExportModel } from "../types";
import { displayScore, displayTotal, formatExportStat } from "./format.ts";
import { prepareScorecardExport } from "./export-preparation.ts";

const escapeHtml = (value: string) => value
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

export type HtmlExport = {
  html: string;
  plain: string;
};

export function scorecardToHtml(model: ScorecardExportModel): HtmlExport {
  const prepared = prepareScorecardExport(model);
  const playerLabels = prepared.playerNames.map(
    (name) => name || "Unnamed player",
  );
  const scoreRows = prepared.scoreRows.map((row) =>
    `<tr><th style="border:1px solid #cbd8c9;padding:8px;text-align:center;font-weight:600">${row.hole}</th>${row.scores.map((score) => `<td style="border:1px solid #cbd8c9;padding:8px;text-align:center">${escapeHtml(displayScore(score))}</td>`).join("")}<td style="border:1px solid #cbd8c9;padding:8px;text-align:center;font-weight:600">${displayTotal(row.total)}</td></tr>`,
  ).join("");
  const leaderboardRows = prepared.leaderboardRows.map((stat) =>
    `<tr><td style="border:1px solid #cbd8c9;padding:8px;text-align:center">${stat.rank}</td><th style="border:1px solid #cbd8c9;padding:8px;text-align:left;font-weight:600">${escapeHtml(stat.name || "Unnamed player")}</th><td style="border:1px solid #cbd8c9;padding:8px;text-align:center">${stat.values.length ? stat.total : "—"}</td><td style="border:1px solid #cbd8c9;padding:8px;text-align:center">${formatExportStat(stat.average, stat.values.length > 0)}</td><td style="border:1px solid #cbd8c9;padding:8px;text-align:center">${formatExportStat(stat.deviation, stat.values.length > 0)}</td><td style="border:1px solid #cbd8c9;padding:8px;text-align:center">${stat.values.length} / ${prepared.game.holes}</td></tr>`,
  ).join("");
  const header = "border:1px solid #cbd8c9;padding:8px;background:#e7f0e5;color:#173b2b;text-align:center;font-weight:700";
  const totalRow = `<tr><th style="border:1px solid #cbd8c9;padding:8px;text-align:center;background:#f0f6ed;font-weight:700">Total</th>${prepared.playerTotals.map((total) => `<td style="border:1px solid #cbd8c9;padding:8px;text-align:center;background:#f0f6ed;font-weight:700">${displayTotal(total)}</td>`).join("")}<td style="border:1px solid #cbd8c9;padding:8px;text-align:center;background:#f0f6ed;font-weight:700">${displayTotal(prepared.grandTotal)}</td></tr>`;
  const html = `<div style="font:16px Arial,sans-serif;color:#173b2b"><h1 style="color:#185c3a">Mini Golf Scorecard — ${prepared.game.holes} Holes</h1><h2 style="margin-top:28px;color:#185c3a">Scorecard</h2><table style="border-collapse:collapse;width:100%;margin-top:10px"><thead><tr><th style="${header}">Hole</th>${playerLabels.map((name) => `<th style="${header}">${escapeHtml(name)}</th>`).join("")}<th style="${header}">Total</th></tr></thead><tbody>${scoreRows}</tbody><tfoot>${totalRow}</tfoot></table><h2 style="margin-top:28px;color:#185c3a">Leaderboard</h2><table style="border-collapse:collapse;width:100%;margin-top:10px"><thead><tr><th style="${header}">Rank</th><th style="${header};text-align:left">Player</th><th style="${header}">Total</th><th style="${header}">Average</th><th style="${header}">Std Deviation</th><th style="${header}">Holes Played</th></tr></thead><tbody>${leaderboardRows}</tbody></table></div>`;
  const plain = [`Mini Golf Scorecard — ${prepared.game.holes} Holes`, "", "Scorecard", ["Hole", ...playerLabels, "Total"].join("\t"), ...prepared.scoreRows.map((row) => [row.hole, ...row.scores.map(displayScore), displayTotal(row.total)].join("\t")), ["Total", ...prepared.playerTotals.map(displayTotal), displayTotal(prepared.grandTotal)].join("\t"), "", "Leaderboard", "Rank\tPlayer\tTotal\tAverage\tStd Deviation\tHoles Played", ...prepared.leaderboardRows.map((stat) => [stat.rank, stat.name || "Unnamed player", stat.values.length ? stat.total : "—", formatExportStat(stat.average, stat.values.length > 0), formatExportStat(stat.deviation, stat.values.length > 0), `${stat.values.length} / ${prepared.game.holes}`].join("\t"))].join("\n");

  return { html, plain };
}

import type { ScorecardExportModel } from "../types";
import { displayScore, displayTotal, formatExportStat } from "./format.ts";
import { prepareScorecardExport } from "./export-preparation.ts";

const escapeXml = (value: string) => value.replace(/[&<>"']/g, (character) => ({
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&apos;",
}[character] ?? character));

export function scorecardToSvg(model: ScorecardExportModel): { svg: string; width: number; height: number } {
  const prepared = prepareScorecardExport(model);
  const margin = 36;
  const holeColumnWidth = 150;
  const totalColumnWidth = 120;
  const width = Math.max(900, margin * 2 + holeColumnWidth + totalColumnWidth + prepared.game.players.length * 150);
  const rowHeight = 60;
  const tableTop = 228;
  const tableHeight = (prepared.game.holes + 2) * rowHeight;
  const leaderboardTop = tableTop + tableHeight + 72;
  const height = leaderboardTop + Math.max(1, prepared.leaderboardRows.length) * 82 + 64;
  const playerWidth = (width - margin * 2 - holeColumnWidth - totalColumnWidth) / Math.max(1, prepared.game.players.length);
  const tableWidth = width - margin * 2;
  const holeCenter = margin + holeColumnWidth / 2;
  const lines: string[] = [];

  lines.push(`<rect width="${width}" height="${height}" rx="28" fill="#f4f5ec"/>`);
  lines.push(`<text x="${margin}" y="82" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="54" font-weight="800">Mini Golf Scorecard</text>`);
  lines.push(`<text x="${margin}" y="132" fill="#6b7e72" font-family="Inter, Arial, sans-serif" font-size="24">${prepared.game.holes} Holes · ${prepared.game.players.length} Players</text>`);
  lines.push(`<rect x="${margin}" y="${tableTop}" width="${tableWidth}" height="${tableHeight}" rx="18" fill="#ffffff" stroke="#dfe6d9"/>`);
  lines.push(`<rect x="${margin}" y="${tableTop}" width="${tableWidth}" height="${rowHeight}" rx="18" fill="#e7f0e5"/>`);
  lines.push(`<text x="${holeCenter}" y="${tableTop + 39}" text-anchor="middle" fill="#6b7e72" font-family="Inter, Arial, sans-serif" font-size="22" font-weight="700">Hole</text>`);

  prepared.game.players.forEach((player, index) => {
    const x = margin + holeColumnWidth + playerWidth * index + playerWidth / 2;
    lines.push(`<text x="${x}" y="${tableTop + 39}" text-anchor="middle" fill="#173b2b" font-family="Inter, Arial, sans-serif" font-size="22" font-weight="700">${escapeXml(player.name || `Player ${index + 1}`)}</text>`);
  });
  lines.push(`<text x="${width - margin - 60}" y="${tableTop + 39}" text-anchor="middle" fill="#6b7e72" font-family="Inter, Arial, sans-serif" font-size="22" font-weight="700">Total</text>`);

  prepared.scoreRows.forEach((row, index) => {
    const y = tableTop + rowHeight * (index + 1);
    lines.push(`<line x1="${margin}" y1="${y}" x2="${margin + tableWidth}" y2="${y}" stroke="#edf0e9"/>`);
    lines.push(`<text x="${holeCenter}" y="${y + 39}" text-anchor="middle" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="24" font-weight="700">${row.hole}</text>`);
    row.scores.forEach((score, playerIndex) => {
      const x = margin + holeColumnWidth + playerWidth * playerIndex + playerWidth / 2;
      lines.push(`<text x="${x}" y="${y + 39}" text-anchor="middle" fill="#173b2b" font-family="Inter, Arial, sans-serif" font-size="26" font-weight="700">${escapeXml(displayScore(score))}</text>`);
    });
    lines.push(`<text x="${width - margin - 60}" y="${y + 39}" text-anchor="middle" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="26" font-weight="700">${displayTotal(row.total)}</text>`);
  });

  const totalsY = tableTop + rowHeight * (prepared.game.holes + 1);
  lines.push(`<line x1="${margin}" y1="${totalsY}" x2="${margin + tableWidth}" y2="${totalsY}" stroke="#dfe6d9"/>`);
  lines.push(`<text x="${holeCenter}" y="${totalsY + 39}" text-anchor="middle" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="24" font-weight="800">Total</text>`);
  prepared.playerTotals.forEach((total, index) => {
    const x = margin + holeColumnWidth + playerWidth * index + playerWidth / 2;
    lines.push(`<text x="${x}" y="${totalsY + 39}" text-anchor="middle" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="26" font-weight="800">${displayTotal(total)}</text>`);
  });
  lines.push(`<text x="${width - margin - 60}" y="${totalsY + 39}" text-anchor="middle" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="26" font-weight="800">${displayTotal(prepared.grandTotal)}</text>`);

  lines.push(`<text x="${margin}" y="${leaderboardTop - 28}" fill="#173b2b" font-family="Inter, Arial, sans-serif" font-size="34" font-weight="800">Leaderboard</text>`);
  prepared.leaderboardRows.forEach((stat, index) => {
    const y = leaderboardTop + index * 104;
    lines.push(`<rect x="${margin}" y="${y}" width="${tableWidth}" height="82" rx="14" fill="#ffffff" stroke="#dfe6d9"/>`);
    lines.push(`<text x="${margin + 24}" y="${y + 51}" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="28" font-weight="800">${stat.rank}</text>`);
    const totalX = margin + tableWidth * 0.39;
    const averageX = margin + tableWidth * 0.67;
    const deviationX = margin + tableWidth * 0.84;
    lines.push(`<text x="${margin + 74}" y="${y + 37}" fill="#173b2b" font-family="Inter, Arial, sans-serif" font-size="24" font-weight="700">${escapeXml(stat.name || `Player ${stat.rank}`)}</text>`);
    lines.push(`<text x="${margin + 74}" y="${y + 64}" fill="#6b7e72" font-family="Inter, Arial, sans-serif" font-size="16">${stat.values.length} / ${prepared.game.holes} Holes Played</text>`);
    lines.push(`<text x="${totalX}" y="${y + 49}" fill="#185c3a" font-family="Inter, Arial, sans-serif" font-size="30" font-weight="800">${stat.values.length ? stat.total : "—"}<tspan dx="8" fill="#6b7e72" font-size="16">Strokes</tspan></text>`);
    lines.push(`<text x="${averageX}" y="${y + 34}" fill="#6b7e72" font-family="Inter, Arial, sans-serif" font-size="15">Average</text><text x="${averageX}" y="${y + 62}" fill="#173b2b" font-family="Inter, Arial, sans-serif" font-size="21" font-weight="700">${formatExportStat(stat.average, stat.values.length > 0)}</text>`);
    lines.push(`<text x="${deviationX}" y="${y + 34}" fill="#6b7e72" font-family="Inter, Arial, sans-serif" font-size="15">Std Deviation</text><text x="${deviationX}" y="${y + 62}" fill="#173b2b" font-family="Inter, Arial, sans-serif" font-size="21" font-weight="700">${formatExportStat(stat.deviation, stat.values.length > 0)}</text>`);
  });

  return {
    svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${lines.join("")}</svg>`,
    width,
    height,
  };
}

@import "tailwindcss";

:root {
  --ink: #173b2b;
  --muted: #6b7e72;
  --green: #185c3a;
  --lime: #c9e85b;
  --cream: #f4f5ec;
  --line: #dfe6d9;
  --white: #fff;
}

.storage-warning {
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 12px;
  background: var(--cream);
  color: var(--ink);
  line-height: 1.5;
}

.account-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 16px 20px;
  margin-bottom: 16px;
}

.account-bar .eyebrow {
  margin-bottom: 4px;
}

.account-status,
.account-message {
  margin: 0;
  color: var(--ink);
  font-size: 13px;
}

.account-message {
  margin-top: 6px;
  color: #8a3f2e;
}

.account-bar a {
  text-decoration: none;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: #173d29;
  /* Original miniature-golf course art generated for Mini Golf Scorecard. */
  background-image:
    linear-gradient(180deg, #0d2c1cc7 0%, #0d2c1ca8 55%, #0d2c1cd1 100%),
    url("/images/mini-golf-course-background.png");
  background-position: center top, center top;
  background-size: cover, cover;
  background-attachment: fixed, fixed;
  color: var(--ink);
  font-family: var(--font-inter), Inter, Arial, Helvetica, sans-serif;
}

button,
input,
select {
  font: inherit;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3,
label,
button,
select,
option,
.eyebrow,
.progress,
.drag-help,
.finish p:not(.eyebrow),
.summary-grid::before,
.summary-card dt,
.big-score span,
.footer-brand,
.footer-tagline {
  text-transform: capitalize;
}

h1 {
  margin-bottom: 0;
  font-size: clamp(28px, 5vw, 44px);
  letter-spacing: -0.055em;
  line-height: 1;
}

h2 {
  margin-bottom: 0;
  font-size: 24px;
  letter-spacing: -0.03em;
}

h3 {
  margin: 0;
  font-size: 16px;
}

/* Shell and shared surfaces */

.shell {
  max-width: 1120px;
  margin: auto;
  padding: 38px 22px 32px;
}

.hero {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-bottom: 30px;
}

.logo-mark {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: transparent url("/app-icon.svg") center / contain no-repeat;
  font-size: 0;
}

.hero h1 {
  color: var(--cream);
  text-shadow: 0 2px 10px #102c1c66;
}

.hero h1 em {
  color: var(--lime);
  font-style: normal;
}

.hero .eyebrow {
  display: none;
}

.eyebrow {
  margin: 0 0 7px;
  color: #668276;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.panel,
.summary-card {
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--white);
  box-shadow: 0 8px 24px #173b2b08;
}

/* Game setup and action controls */

.setup {
  display: flex;
  align-items: end;
  gap: 18px;
  padding: 20px;
  margin-bottom: 16px;
}

.field {
  min-width: 150px;
}

.field label {
  display: block;
  margin-bottom: 7px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

select {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 11px 12px;
  color: var(--ink);
  background: #fbfcf7;
}

.setup-actions {
  display: flex;
  gap: 8px;
  margin-left: auto;
}

.button {
  border: 0;
  border-radius: 10px;
  padding: 11px 15px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 700;
  transition: transform 0.15s;
}

.button:hover {
  transform: translateY(-1px);
}

.primary {
  color: #fff;
  background: var(--green);
}

.secondary,
.compact-toggle {
  color: var(--green);
  background: #e7f0e5;
}

.ghost {
  color: var(--muted);
  background: transparent;
}

/* Score table */

.score-panel {
  padding: 20px;
  overflow: hidden;
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 18px;
}

.section-heading h2,
.finish h2 {
  text-transform: none;
}

.heading-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.progress {
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
}

.compact-toggle {
  padding: 7px 10px;
  font-size: 11px;
}

.table-size-control {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.table-size-control select {
  width: auto;
  border-radius: 8px;
  padding: 6px 8px;
  color: var(--green);
  background: #edf4e8;
  font-size: 11px;
  font-weight: 700;
}

.table-wrap {
  overflow-x: auto;
}

.score-panel table {
  width: max-content;
  min-width: 0;
  border-collapse: collapse;
  table-layout: fixed;
}

.score-panel .hole-col {
  width: 64px;
}

.score-panel .total-col {
  width: 76px;
}

th,
td {
  border-bottom: 1px solid #edf0e9;
  padding: 8px 7px;
  text-align: center;
}

thead th {
  position: relative;
  padding-top: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  user-select: none;
}

.score-panel thead th:first-child,
.score-panel thead th:last-child {
  vertical-align: middle;
  padding-top: 7px;
}

.score-panel thead th:first-child,
.score-panel tbody th {
  text-align: center;
}

tbody th {
  width: auto;
  color: var(--muted);
  font-size: 13px;
}

.score-panel tbody th {
  position: relative;
  padding-left: 0;
  padding-right: 0;
}

tbody tr:last-child td,
tbody tr:last-child th {
  border-bottom: 0;
}

.score-panel tfoot th,
.score-panel tfoot td {
  border-top: 2px solid var(--line);
  background: #f0f6ed;
  color: var(--green);
  font-weight: 800;
}

.name-input {
  width: 100%;
  min-width: 85px;
  border: 0;
  border-bottom: 2px solid var(--green);
  padding: 7px 3px;
  outline: 0;
  color: var(--ink);
  background: transparent;
  font-size: 19px;
  font-weight: 800;
  text-align: center;
  user-select: text;
}

.score-input {
  width: 54px;
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 9px 4px;
  outline: 0;
  color: var(--ink);
  background: #fbfcf7;
  font-weight: 700;
  -moz-appearance: textfield;
  letter-spacing: 0;
  text-align: center;
}

.score-input:focus,
.name-input:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px #185c3a1c;
}

.hole-number {
  display: inline-grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 50%;
  color: var(--green);
  background: #edf3e8;
  font-weight: 700;
}

.score-panel .tick {
  position: absolute;
  top: 50%;
  left: calc(75% + 6.25px);
  color: var(--green);
  transform: translate(-50%, -50%);
}

.hole-total {
  color: var(--green);
  font-weight: 700;
}

.score-panel .hole-winner {
  background: #eff8c7;
  box-shadow: inset 0 0 0 2px #c9e85b;
}

.score-panel .hole-winner .score-input {
  border-color: #99b642;
  background: #f8fbdc;
}

.score-panel .hole-tie {
  background: #e7ddff;
  box-shadow: inset 0 0 0 2px #a789e8;
}

.score-panel .hole-tie .score-input {
  border-color: #9b7bd9;
  background: #f4efff;
}

/* Score controls and player-column interactions */

.score-control {
  position: relative;
  display: block;
  width: 100%;
  vertical-align: middle;
}

.score-control .score-input {
  display: block;
  margin: 0 auto;
}

.score-stepper {
  position: absolute;
  top: 50%;
  left: calc(50% + 30px);
  display: flex;
  width: 20px;
  height: calc(1.2em + 20px);
  flex-direction: column;
  gap: 1px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-50%);
  transition: opacity 0.12s ease;
}

.score-stepper button {
  width: 20px;
  height: auto;
  flex: 1;
  border: 1px solid var(--line);
  border-radius: 3px;
  padding: 0;
  cursor: pointer;
  color: var(--green);
  background: #edf4e8;
  font-size: 8px;
  line-height: 9px;
}

.score-stepper button:hover {
  background: var(--lime);
}

.score-control:focus-within .score-stepper,
.score-control:hover .score-stepper,
.score-panel tbody td:hover .score-stepper {
  opacity: 1;
  pointer-events: auto;
}

.score-input::-webkit-inner-spin-button,
.score-input::-webkit-outer-spin-button {
  margin: 0;
  -webkit-appearance: none;
}

@media (max-width: 650px), (hover: none) and (pointer: coarse) {
  .score-stepper {
    display: none;
  }
}

.drag-handle {
  display: inline-block;
  margin-right: 5px;
  color: #8aa193;
  cursor: grab;
  font-size: 15px;
  user-select: none;
  vertical-align: -1px;
  touch-action: none;
}

.drag-handle:active {
  cursor: grabbing;
}

.score-panel .drag-handle {
  -webkit-user-drag: none;
}

.player-move { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px; }
.player-move button {
  min-width: 44px; min-height: 44px; border: 0; border-radius: 5px;
  padding: 0; color: var(--green); background: #edf4e8;
  font-size: 1.25rem; font-weight: 700; line-height: 1;
}
.player-move button:disabled { opacity: 0.35; }
.player-move button:focus-visible, .resize-handle:focus-visible {
  outline: 3px solid var(--green); outline-offset: 2px;
}
.score-entry-error { color: #852b20; }
.score-entry-error:empty { display: none; }

.score-panel th.dragging {
  opacity: 0.45;
  user-select: none;
}

.resize-handle {
  position: absolute;
  z-index: 3;
  top: 8px;
  right: -12px;
  bottom: 4px;
  width: 24px;
  cursor: col-resize;
  touch-action: none;
}

.resize-handle::after {
  position: absolute;
  top: 8px;
  bottom: 4px;
  left: 50%;
  width: 2px;
  background: #b8c9b7;
  content: "";
  transform: translateX(-50%);
}

.resize-handle:hover::after {
  background: var(--green);
}

.drop-target.before {
  box-shadow: inset 4px 0 0 var(--lime);
}

.drop-target.after {
  box-shadow: inset -4px 0 0 var(--lime);
}

.score-panel thead th.drop-target {
  box-shadow: none;
}

.score-panel thead th.drop-target.before::after {
  position: absolute;
  z-index: 4;
  top: 8px;
  bottom: 4px;
  left: -1px;
  width: 3px;
  background: var(--lime);
  content: "";
}

.score-panel thead th.drop-target.before .resize-handle::after {
  background: transparent;
}

.score-panel thead th.drop-target.after .resize-handle::after {
  width: 3px;
  background: var(--lime);
}

body:has(.score-panel thead th.dragging),
body:has(.score-panel thead th.dragging) * {
  cursor: grabbing !important;
}

/* Leaderboard */

.summary-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 16px 0;
  counter-reset: leaderboard;
}

.summary-grid::before {
  display: block;
  color: #fff;
  content: "Leaderboard";
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.summary-card,
.summary-card.leader {
  position: relative;
  display: grid;
  grid-template-columns: 56px minmax(180px, 1fr) 150px minmax(360px, 1.8fr);
  align-items: center;
