"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { PointerEvent as ReactPointerEvent } from "react";
import {
  DEFAULT_COLUMN_WIDTH,
  MIN_COLUMN_WIDTH,
  getAutomaticColumnWidth,
  resizeColumnWidth,
} from "../domain/player-layout";
import type { Player } from "../types";

export type ColumnSizingLayout = ReturnType<typeof useColumnSizing>;

export function useColumnSizing(players: Player[]) {
  const nameInputRef = useRef<HTMLInputElement | null>(null);
  const pointerCleanup = useRef<(() => void) | null>(null);
  const [widths, setWidths] = useState<Record<string, number>>({});

  const registerNameInput = useCallback((element: HTMLInputElement | null) => {
    nameInputRef.current = element;
  }, []);

  const resizeColumn = useCallback(
    (event: ReactPointerEvent<HTMLSpanElement>, playerId: string) => {
      event.preventDefault();
      event.stopPropagation();
      pointerCleanup.current?.();
      const start = event.clientX;
      const initial = widths[playerId] ?? DEFAULT_COLUMN_WIDTH;
      const move = (nextEvent: PointerEvent) => {
        setWidths((current) => ({
          ...current,
          [playerId]: resizeColumnWidth(initial, nextEvent.clientX - start),
        }));
      };
      const end = () => {
        pointerCleanup.current?.();
      };

      const cleanup = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", end);
        window.removeEventListener("pointercancel", end);
        if (pointerCleanup.current === cleanup) pointerCleanup.current = null;
      };
      pointerCleanup.current = cleanup;
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", end);
      window.addEventListener("pointercancel", end);
    },
    [widths],
  );

  const resizeColumnBy = useCallback((playerId: string, delta: number | "minimum") => {
    pointerCleanup.current?.();
    setWidths(current => ({ ...current, [playerId]: delta === "minimum" ? MIN_COLUMN_WIDTH : resizeColumnWidth(current[playerId] ?? DEFAULT_COLUMN_WIDTH, delta) }));
  }, []);

  useEffect(() => () => pointerCleanup.current?.(), []);

  const autoColumns = useCallback(() => {
    const canvas = document.createElement("canvas");
    const context = canvas.getContext("2d");
    const input = nameInputRef.current;
    if (context && input) context.font = getComputedStyle(input).font;

    const width = getAutomaticColumnWidth(
      players,
      (value) => context?.measureText(value).width ?? 90,
    );
    setWidths(Object.fromEntries(players.map((player) => [player.id, width])));
  }, [players]);

  return {
    widths,
    registerNameInput,
    resizeColumn,
    resizeColumnBy,
    autoColumns,
  };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { DragEvent, PointerEvent as ReactPointerEvent } from "react";
import { getDropPosition, type DropPosition } from "../domain/player-layout";
import type { Player } from "../types";

export type PlayerReorderingLayout = ReturnType<typeof usePlayerReordering>;

export function usePlayerReordering(
  players: Player[],
  onReorder: (fromId: string, toId: string, after?: boolean) => void,
) {
  const headerRefs = useRef<Record<string, HTMLTableCellElement | null>>({});
  const pointerCleanup = useRef<(() => void) | null>(null);
  const [dragging, setDragging] = useState<string | null>(null);
  const [dropTarget, setDropTarget] = useState<string | null>(null);
  const [dropSide, setDropSide] = useState<"before" | "after">("before");

  const registerHeader = useCallback(
    (playerId: string, element: HTMLTableCellElement | null) => {
      if (element) headerRefs.current[playerId] = element;
      else delete headerRefs.current[playerId];
    },
    [],
  );

  const clearDragging = useCallback(() => {
    setDragging(null);
    setDropTarget(null);
    setDropSide("before");
  }, []);

  const startDragging = useCallback((playerId: string) => {
    setDragging(playerId);
  }, []);

  const markDropTarget = useCallback((playerId: string) => {
    setDropTarget(playerId);
  }, []);

  const dropPlayer = useCallback(
    (targetId: string, after = false) => {
      if (dragging) onReorder(dragging, targetId, after);
      clearDragging();
    },
    [clearDragging, dragging, onReorder],
  );

  const handleHeaderDragOver = useCallback(
    (event: DragEvent<HTMLElement>, playerId: string) => {
      event.preventDefault();
      const rect = event.currentTarget.getBoundingClientRect();
      setDropTarget(playerId);
      setDropSide(event.clientX >= rect.left + rect.width / 2 ? "after" : "before");
    },
    [],
  );

  const pointerDrag = useCallback(
    (event: ReactPointerEvent<HTMLSpanElement>, playerId: string) => {
      event.preventDefault();
      event.stopPropagation();
      pointerCleanup.current?.();
      setDragging(playerId);

      let position: DropPosition = null;
      const move = (nextEvent: PointerEvent) => {
        const headers = players.flatMap((player) => {
          const element = headerRefs.current[player.id];
          if (!element) return [];
          const rect = element.getBoundingClientRect();
          return [{ id: player.id, left: rect.left, right: rect.right }];
        });
        position = getDropPosition(headers, playerId, nextEvent.clientX);
        setDropTarget(position?.targetId ?? null);
        setDropSide(position?.after ? "after" : "before");
      };

      const end = () => {
        if (position) onReorder(playerId, position.targetId, position.after);
        clearDragging();
        pointerCleanup.current?.();
      };

      const cancel = () => {
        clearDragging();
        pointerCleanup.current?.();
      };

      const cleanup = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", end);
        window.removeEventListener("pointercancel", cancel);
        if (pointerCleanup.current === cleanup) pointerCleanup.current = null;
      };

      pointerCleanup.current = cleanup;
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", end);
      window.addEventListener("pointercancel", cancel);
    },
    [clearDragging, onReorder, players],
  );

  useEffect(() => () => pointerCleanup.current?.(), []);

  return {
    dragging,
    dropTarget,
    dropSide,
    registerHeader,
    pointerDrag,
    startDragging,
    markDropTarget,
    clearDragging,
    handleHeaderDragOver,
    dropPlayer,
  };
}

"use client";

import { useCallback, useEffect, useState } from "react";
import {
  adjustScore,
  createGame,
  DEFAULT_HOLES,
  DEFAULT_PLAYERS,
  movePlayer,
  renamePlayer,
  reorderPlayers,
  resetScores,
  resizeHoles,
  resizePlayers,
  setScore,
} from "../domain/scorecard";
import { loadGameState, saveGame } from "../scorecard-storage";
import type { Game } from "../types";

function createHydrationGame(): Game {
  let nextId = 0;
  return createGame(DEFAULT_HOLES, DEFAULT_PLAYERS, () => `initial-player-${++nextId}`);
}

export function useScorecardGame() {
  const [game, setGame] = useState<Game>(createHydrationGame);
  const [hasLoadedStorage, setHasLoadedStorage] = useState(false);
  const [canSave, setCanSave] = useState(false);
  const [storageWarning, setStorageWarning] = useState<string | null>(null);

  useEffect(() => {
    const loadStoredGame = window.setTimeout(() => {
      const loaded = loadGameState();
      setGame(loaded.game);
      setCanSave(loaded.writable);
      if (!loaded.writable) setStorageWarning("Saved scores could not be loaded. This round is not being saved. Download your scores before closing this page.");
      setHasLoadedStorage(true);
    }, 0);
    return () => window.clearTimeout(loadStoredGame);
  }, []);

  useEffect(() => {
    if (!hasLoadedStorage || !canSave) return;
    let cancelled = false;
    const saved = saveGame(game);
    queueMicrotask(() => {
      if (!cancelled) setStorageWarning(saved ? null : "Scores could not be saved on this device. Download your scores before closing this page.");
    });
    return () => { cancelled = true; };
  }, [game, hasLoadedStorage, canSave]);

  const changeHoles = useCallback((holes: number) => {
    setGame((current) => resizeHoles(current, holes));
  }, []);

  const changePlayers = useCallback((playerCount: number) => {
    setGame((current) => resizePlayers(current, playerCount));
  }, []);

  const changeScore = useCallback((playerId: string, hole: number, value: string) => {
    setGame((current) => setScore(current, playerId, hole, value));
  }, []);

  const changeScoreBy = useCallback(
    (playerId: string, hole: number, delta: number) => {
      setGame((current) => adjustScore(current, playerId, hole, delta));
    },
    [],
  );

  const changePlayerName = useCallback((playerId: string, name: string) => {
    setGame((current) => renamePlayer(current, playerId, name));
  }, []);

  const reset = useCallback(() => {
    setGame((current) => resetScores(current));
  }, []);

  const startNewGame = useCallback(() => {
    setGame(createGame());
  }, []);

  const reorder = useCallback((fromId: string, toId: string, after = false) => {
    setGame((current) => reorderPlayers(current, fromId, toId, after));
  }, []);

  const move = useCallback((playerId: string, direction: -1 | 1) => {
    setGame((current) => movePlayer(current, playerId, direction));
  }, []);

  return {
    game,
    storageWarning,
    changeHoles,
    changePlayers,
    changeScore,
    changeScoreBy,
    changePlayerName,
    reset,
    startNewGame,
    reorder,
    move,
  };
}

"use client";

import { useEffect, useState } from "react";
import {
  loadTableTextSize,
  saveTableTextSize,
} from "../scorecard-storage";
import type { TextSize } from "../types";

export function useTableTextSize() {
  const [tableSize, setTableSize] = useState<TextSize>("medium");
  const [hasLoadedStorage, setHasLoadedStorage] = useState(false);

  useEffect(() => {
    const loadStoredTableSize = window.setTimeout(() => {
      setTableSize(loadTableTextSize());
      setHasLoadedStorage(true);
    }, 0);
    return () => window.clearTimeout(loadStoredTableSize);
  }, []);

  useEffect(() => {
    if (hasLoadedStorage) saveTableTextSize(tableSize);
  }, [hasLoadedStorage, tableSize]);

  return [tableSize, setTableSize] as const;
}

