"use client";

import { useEffect, useMemo, useState } from "react";
import { GameSetup } from "./components/game-setup";
import { Leaderboard } from "./components/leaderboard";
import { ScoreTable } from "./components/score-table";
import { ShareActions } from "./components/share-actions";
import { buildExportModel } from "./domain/scorecard";
import { useColumnSizing } from "./hooks/use-column-sizing";
import { usePlayerReordering } from "./hooks/use-player-reordering";
import { useScorecardGame } from "./hooks/use-scorecard-game";
import { useTableTextSize } from "./hooks/use-table-text-size";

export default function Home() {
  const [accountState, setAccountState] = useState<"loading" | "signed_out" | "signed_in">("loading");
  const [accountMessage, setAccountMessage] = useState("");
  const scorecard = useScorecardGame();
  const [tableSize, setTableSize] = useTableTextSize();
  const playerReordering = usePlayerReordering(scorecard.game.players, scorecard.reorder);
  const columnSizing = useColumnSizing(scorecard.game.players);
  const layout = { ...playerReordering, ...columnSizing };
  const exportModel = useMemo(() => buildExportModel(scorecard.game), [scorecard.game]);

  useEffect(() => {
    fetch("/api/auth/session", { cache: "no-store", credentials: "same-origin" })
      .then((response) => response.json() as Promise<{ authenticated?: boolean }>)
      .then((result) => setAccountState(result.authenticated === true ? "signed_in" : "signed_out"))
      .catch(() => {
        setAccountState("signed_out");
        setAccountMessage("ACM Account is unavailable right now. Your scorecard is still available locally.");
      });
  }, []);

  async function signOut() {
    setAccountMessage("");
    const response = await fetch("/api/auth/signout", { method: "POST", credentials: "same-origin" });
    if (response.ok) setAccountState("signed_out");
    else setAccountMessage("We could not sign you out. Please try again.");
  }

  return (
    <main className="shell">
      <header className="hero">
        <div className="logo-mark">⛳</div>
        <div>
          <p className="eyebrow">A little friendly competition</p>
          <h1>Mini golf <em>scorecard</em></h1>
        </div>
      </header>

      <section className="account-bar panel" aria-label="ACM Account">
        <div>
          <p className="eyebrow">ACM Account</p>
          <p className="account-status" role="status">
            {accountState === "loading" ? "Checking your ACM Account connection…" : accountState === "signed_in" ? "Signed in with ACM Account" : "Playing as a guest"}
          </p>
          {accountMessage || new URLSearchParams(typeof window === "undefined" ? "" : window.location.search).has("auth_error") ? <p className="account-message" role="alert">{accountMessage || "We could not connect to ACM Account. You can try again."}</p> : null}
        </div>
        {accountState === "loading" ? null : accountState === "signed_in" ? (
          <button className="button secondary" type="button" onClick={signOut}>Sign out</button>
        ) : (
          <a className="button primary" href="/api/auth/start?return_to=/">Sign in with ACM Account</a>
        )}
      </section>

      {scorecard.storageWarning ? <p className="storage-warning" role="status">{scorecard.storageWarning}</p> : null}

      <GameSetup
        game={scorecard.game}
        onHolesChange={scorecard.changeHoles}
        onPlayersChange={scorecard.changePlayers}
        onReset={scorecard.reset}
        onNewGame={scorecard.startNewGame}
      />

      <ScoreTable
        game={scorecard.game}
        exportModel={exportModel}
        tableSize={tableSize}
        layout={layout}
        onTableSizeChange={setTableSize}
        onAutoResize={layout.autoColumns}
        onScore={scorecard.changeScore}
        onAdjustScore={scorecard.changeScoreBy}
        onPlayerNameChange={scorecard.changePlayerName}
        onMovePlayer={scorecard.move}
      />

      <Leaderboard stats={exportModel.stats} holes={scorecard.game.holes} />
      <ShareActions model={exportModel} />
    </main>
  );
}

import { createGame, parseScore } from "./domain/scorecard.ts";
import type { Game, TextSize } from "./types";

export const GAME_STORAGE_KEY = "mini-golf-scorecard-game";
export const TABLE_SIZE_STORAGE_KEY = "mini-golf-scorecard-table-size";

type StorageLike = Pick<Storage, "getItem" | "setItem">;

function getBrowserStorage(): StorageLike | null {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function parseStoredGame(value: string | null): Game | null {
  if (!value) return null;

  try {
    const parsed: unknown = JSON.parse(value);
    if (!isRecord(parsed)) return null;
    const holes = parsed.holes;
    if (
      typeof holes !== "number" ||
      !Number.isInteger(holes) ||
      holes < 1 ||
      holes > 18 ||
      !Array.isArray(parsed.players) ||
      parsed.players.length < 1 ||
      parsed.players.length > 8 ||
      !isRecord(parsed.scores)
    ) {
      return null;
    }

    const players = parsed.players.map((player) => {
      if (!isRecord(player) || typeof player.id !== "string" || typeof player.name !== "string") {
        throw new Error("Invalid player");
      }
      return { id: player.id, name: player.name };
    });

    if (new Set(players.map((player) => player.id)).size !== players.length) {
      return null;
    }

    const scores: Record<string, string[]> = {};
    for (const player of players) {
      const playerScores = parsed.scores[player.id];
      if (!Array.isArray(playerScores) || playerScores.length !== holes) {
        return null;
      }
      if (!playerScores.every((score) => typeof score === "string" && parseScore(score) !== null)) return null;
      scores[player.id] = [...playerScores];
    }

    return { holes, players, scores };
  } catch {
    return null;
  }
}

export function loadGame(storage: StorageLike | null = getBrowserStorage()): Game {
  return loadGameState(storage).game;
}

export function loadGameState(storage: StorageLike | null = getBrowserStorage()): { game: Game; writable: boolean } {
  try {
    if (!storage) return { game: createGame(), writable: false };
    const raw = storage.getItem(GAME_STORAGE_KEY);
    const stored = parseStoredGame(raw);
    return { game: stored ?? createGame(), writable: raw === null || stored !== null };
  } catch {
    // Never overwrite an unreadable saved game with the fallback round.
    return { game: createGame(), writable: false };
  }
}

export function saveGame(game: Game, storage: StorageLike | null = getBrowserStorage()): boolean {
  try {
    if (!storage) return false;
    const raw = JSON.stringify(game);
    if (!parseStoredGame(raw)) return false;
    storage.setItem(GAME_STORAGE_KEY, raw);
    return true;
  } catch {
    // Local storage can be unavailable or full. The in-memory game remains usable.
    return false;
  }
}

export function loadTableTextSize(
  storage: StorageLike | null = getBrowserStorage(),
): TextSize {
  try {
    const value = storage?.getItem(TABLE_SIZE_STORAGE_KEY);
    return value === "small" || value === "large" ? value : "medium";
  } catch {
    return "medium";
  }
}

export function saveTableTextSize(
  value: TextSize,
  storage: StorageLike | null = getBrowserStorage(),
): void {
  try {
    storage?.setItem(TABLE_SIZE_STORAGE_KEY, value);
  } catch {
    // A view preference should never prevent score entry.
  }
}

export type Player = {
  id: string;
  name: string;
};

export type Game = {
  holes: number;
  players: Player[];
  scores: Record<string, string[]>;
};

export type PlayerStats = Player & {
  values: number[];
  total: number;
  average: number;
  deviation: number;
};

export type ScorecardExportModel = {
  game: Game;
  stats: PlayerStats[];
  playerTotals: number[];
  holeTotals: number[];
  grandTotal: number;
};

export type TextSize = "small" | "medium" | "large";

