export default config;

import assert from "node:assert/strict";
import test from "node:test";

async function render() {
  const workerUrl = new URL("../dist/server/index.js", import.meta.url);
  workerUrl.searchParams.set("test", `${process.pid}-${Date.now()}`);
  const { default: worker } = await import(workerUrl.href);
  return worker.fetch(new Request("http://localhost/", { headers: { accept: "text/html" } }), { ASSETS: { fetch: async () => new Response("Not found", { status: 404 }) } }, { waitUntil() {}, passThroughOnException() {} });
}

test("server-renders the mini golf scorecard", async () => {
  const response = await render();
  assert.equal(response.status, 200);
  const html = await response.text();
  assert.match(html, /<title>Mini golf scorecard<\/title>/i);
  assert.match(html, /Mini Golf Scorecard/);
  assert.match(html, /Enter your scores/);
  assert.match(html, /Download for Excel/);
  assert.match(html, /Copy as HTML/);
  assert.match(html, /Copy Screenshot/);
  assert.match(html, /score-stepper/);
  assert.equal([...html.matchAll(/class="player-move"/g)].length, 2);
  assert.match(html, /Move Player 1 right/);
  assert.equal([...html.matchAll(/role="separator"/g)].length, 2);
  assert.match(html, /aria-valuemin="68"/);
  assert.match(html, /id="score-entry-error"[^>]*role="alert"/);
  assert.doesNotMatch(html.match(/<section class="summary-grid">[\s\S]*?<\/section>/)?.[0] ?? '', /draggable/);
  assert.match(html, /Increase Player 1, hole 1/);
  assert.match(html, /Decrease Player 1, hole 1/);
  assert.match(html, /© 2026 Mini Golf Scorecard\. All Rights Reserved\./);
  assert.match(html, /https:\/\/uk\.linkedin\.com\/in\/andrewcharlesmoss/);
  assert.match(html, /https:\/\/buymeacoffee\.com\/andrewcharlesmoss/);
  assert.match(html, /linkedin-social-icon/);
  assert.match(html, /coffee-social-icon/);
  assert.doesNotMatch(html, /Keep score\. Have fun\. Play another round\./);
  assert.doesNotMatch(html, /Your site is taking shape|react-loading-skeleton|codex-preview/);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import vm from 'node:vm';
import ts from 'typescript';
import { createGame, setScore, movePlayer, resetScores, buildExportModel } from '../app/domain/scorecard.ts';
const require = createRequire(import.meta.url);
function harness() {
  let cursor = 0; const slots = [], effects = [], nodes = new Map(), listeners = new Map(); let focused;
  const react = {
    useState(initial) { const index = cursor++; if (!(index in slots)) slots[index] = typeof initial === 'function' ? initial() : initial; return [slots[index], value => { slots[index] = typeof value === 'function' ? value(slots[index]) : value; }]; },
    useRef(initial) { const index = cursor++; return slots[index] ??= { current: initial }; },
    useCallback: callback => callback, useEffect() {}, useLayoutEffect: callback => effects.push(callback),
  };
  const cache = new Map();
  function load(file) {
    if (cache.has(file)) return cache.get(file);
    const loadedModule = { exports: {} }; cache.set(file, loadedModule.exports);
    const source = ts.transpileModule(readFileSync(file, 'utf8'), { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022, jsx: ts.JsxEmit.ReactJSX } }).outputText;
    vm.runInNewContext(source, { module: loadedModule, exports: loadedModule.exports, document: { getElementById: id => nodes.get(id) }, window: { addEventListener: (name, callback) => listeners.set(name, callback), removeEventListener: name => listeners.delete(name) },
      require: name => name === 'react' ? react : name.startsWith('.') ? load(path.resolve(path.dirname(file), path.extname(name) ? name : `${name}.ts`)) : require(name),
    });
    return loadedModule.exports;
  }
  const component = load(new URL('../app/components/score-table.tsx', import.meta.url).pathname).ScoreTable;
  const sizing = load(new URL('../app/hooks/use-column-sizing.ts', import.meta.url).pathname).useColumnSizing;
  const reordering = load(new URL('../app/hooks/use-player-reordering.ts', import.meta.url).pathname).usePlayerReordering;
  return { listeners, focused: () => focused,
    render(props) {
      cursor = 0; effects.length = 0; const tree = component(props); nodes.clear();
      function visit(element) {
        if (!element || typeof element !== 'object') return;
        if (Array.isArray(element)) { element.forEach(visit); return; }
        if (element.props?.id) nodes.set(element.props.id, { ...element.props, focus: () => { focused = element.props.id; } });
        visit(element.props?.children);
      }
      visit(tree); effects.forEach(callback => callback());
      return { tree, nodes };
    },
    sizing(players) { cursor = 0; return sizing(players); },
    reordering(players, move) { cursor = 0; return reordering(players, move); },
  };
}
function fixture() {
  let id = 0; const h = harness(); let game = createGame(2, 2, () => `p${++id}`);
  const props = () => ({ game, exportModel: buildExportModel(game), tableSize: 'medium', layout: { widths: {}, registerHeader() {}, registerNameInput() {} },
    onScore: (id, hole, value) => { game = setScore(game, id, hole, value); }, onMovePlayer: (id, direction) => { game = movePlayer(game, id, direction); },
  });
  return { h, game: () => game, reset: () => { game = resetScores(game); }, render: () => h.render(props()) };
}
test('actual score control rejects invalid pasted text, keeps previous score and clears feedback on reset', () => {
  const f = fixture(); let view = f.render(); view.nodes.get('p1-0').onChange({ target: { value: '03' } }); view = f.render();
  assert.equal(f.game().scores.p1[0], '03');
  view.nodes.get('p1-0').onChange({ target: { value: '3e2' } }); view = f.render();
  assert.equal(f.game().scores.p1[0], '03'); assert.equal(view.nodes.get('p1-0')['aria-invalid'], true);
  assert.match(view.nodes.get('score-entry-error').children, /previous score has been kept/);
  f.reset(); view = f.render(); assert.equal(view.nodes.get('score-entry-error').children, '');
});
test('actual move buttons keep focus with the moved player and choose the enabled boundary fallback', () => {
  const f = fixture(); let view = f.render(); view.nodes.get('move-p1-1').onClick(); view = f.render();
  assert.deepEqual(f.game().players.map(player => player.id), ['p2','p1']); assert.equal(f.h.focused(), 'move-p1--1');
  view.nodes.get('move-p1--1').onClick(); f.render(); assert.equal(f.h.focused(), 'move-p1-1');
});
test('column resizing uses the same minimum for keyboard and pointer; cancel removes listeners', () => {
  const h = harness(); const players = [{ id: 'p1', name: 'Player' }]; let sizing = h.sizing(players);
  sizing.resizeColumnBy('p1', -1000); sizing = h.sizing(players); assert.equal(sizing.widths.p1, 68);
  sizing.resizeColumnBy('p1', 10); sizing = h.sizing(players); assert.equal(sizing.widths.p1, 78);
  sizing.resizeColumn({ clientX: 100, preventDefault() {}, stopPropagation() {} }, 'p1');
  h.listeners.get('pointermove')({ clientX: 120 }); sizing = h.sizing(players); assert.equal(sizing.widths.p1, 98);
  h.listeners.get('pointercancel')(); assert.equal(h.listeners.size, 0);
});
test('cancelled pointer reordering never commits a move', () => {
  const h = harness(); let moves = 0; const players = [{ id: 'p1' }, { id: 'p2' }]; const layout = h.reordering(players, () => moves++);
  layout.registerHeader('p1', { getBoundingClientRect: () => ({ left: 0, right: 100 }) }); layout.registerHeader('p2', { getBoundingClientRect: () => ({ left: 100, right: 200 }) });
