import assert from "node:assert/strict";
import test from "node:test";
import {
  adjustScore,
  buildExportModel,
  createGame,
  getHoleResultClass,
  getHoleWinners,
  getPlayerStats,
  movePlayer,
  renamePlayer,
  reorderPlayers,
  resizeHoles,
  resizePlayers,
  setScore,
} from "../app/domain/scorecard.ts";
import {
  getAutomaticColumnWidth,
  getDropPosition,
  resizeColumnWidth,
} from "../app/domain/player-layout.ts";
import { parseStoredGame } from "../app/scorecard-storage.ts";
import { scorecardToCsv } from "../app/exports/csv.ts";
import { scorecardToHtml } from "../app/exports/html.ts";
import { scorecardToSvg } from "../app/exports/image.ts";
import { prepareScorecardExport } from "../app/exports/export-preparation.ts";
import { downloadScorecardCsv } from "../app/exports/download-csv.ts";

function sampleGame() {
  let nextId = 0;
  const ids = () => `player-${++nextId}`;
  let game = createGame(3, 3, ids);
  game = setScore(game, "player-1", 0, "2");
  game = setScore(game, "player-1", 1, "4");
  game = setScore(game, "player-2", 0, "2");
  game = setScore(game, "player-2", 1, "3");
  game = setScore(game, "player-3", 0, "5");
  return game;
}

test("calculates player statistics and hole winners", () => {
  const game = sampleGame();
  const stats = getPlayerStats(game);

  assert.equal(stats[0].id, "player-2");
  assert.equal(stats[0].total, 5);
  assert.equal(stats[0].average, 2.5);
  assert.equal(stats[0].deviation, 0.5);
  assert.deepEqual(getHoleWinners(game, 0), ["player-1", "player-2"]);
  assert.equal(getHoleResultClass(game, 0, "player-1"), "hole-tie");
  assert.equal(getHoleResultClass(game, 0, "player-3"), "");
});

test("preserves scores while changing game dimensions", () => {
  const game = sampleGame();
  const withMoreHoles = resizeHoles(game, 5);
  assert.equal(withMoreHoles.scores["player-1"][1], "4");
  assert.equal(withMoreHoles.scores["player-1"].length, 5);

  const withFewerPlayers = resizePlayers(withMoreHoles, 2);
  assert.deepEqual(withFewerPlayers.players.map((player) => player.id), ["player-1", "player-2"]);
  assert.equal(withFewerPlayers.scores["player-2"][1], "3");
});

test("updates, adjusts and reorders players without mutating the original game", () => {
  const game = sampleGame();
  const adjusted = adjustScore(game, "player-1", 0, 1);
  assert.equal(adjusted.scores["player-1"][0], "3");
  assert.equal(game.scores["player-1"][0], "2");

  const reordered = reorderPlayers(adjusted, "player-3", "player-1");
  assert.deepEqual(reordered.players.map((player) => player.id), ["player-3", "player-1", "player-2"]);
  const moved = movePlayer(reordered, "player-3", 1);
  assert.deepEqual(moved.players.map((player) => player.id), ["player-1", "player-3", "player-2"]);
});

test("calculates drop positions and column widths at their boundaries", () => {
  const headers = [
    { id: "player-1", left: 0, right: 100 },
    { id: "player-2", left: 100, right: 220 },
    { id: "player-3", left: 220, right: 360 },
  ];

  assert.deepEqual(getDropPosition(headers, "player-1", 360), { targetId: "player-3", after: true });
  assert.deepEqual(getDropPosition(headers, "player-3", 0), { targetId: "player-1", after: false });
  assert.equal(getDropPosition(headers, "player-2", 150), null);
  assert.equal(getDropPosition(headers, "missing", 360), null);

  assert.equal(resizeColumnWidth(120, -100), 68);
  assert.equal(resizeColumnWidth(120, 20), 140);
  assert.equal(getAutomaticColumnWidth([{ id: "short", name: "A" }], () => 10), 90);
  assert.equal(getAutomaticColumnWidth([{ id: "long", name: "A long name" }], (value) => value.length * 10), 154);
});

test("rejects malformed stored games and accepts the compatible current shape", () => {
  assert.equal(parseStoredGame("not json"), null);
  assert.equal(parseStoredGame(JSON.stringify({ holes: 99 })), null);

  const game = sampleGame();
  assert.deepEqual(parseStoredGame(JSON.stringify(game)), game);
});

test("builds one export model for CSV consumers", () => {
  const model = buildExportModel(sampleGame());
  assert.deepEqual(model.playerTotals, [6, 5, 5]);
  assert.deepEqual(model.holeTotals, [9, 7, 0]);
  assert.equal(model.grandTotal, 16);

  const csv = scorecardToCsv(model);
  assert.match(csv, /"Hole","Player 1","Player 2","Player 3","Total"/);
  assert.match(csv, /"Leaderboard"\n/);
  assert.match(csv, /"Rank","Player","Total","Average","Std Deviation","Holes Played"/);
});

test("downloads the shared CSV through an injectable browser adapter", async () => {
  const captured = { blob: undefined as Blob | undefined };
  let revokedUrl = "";
  let clicked = false;
  const anchor = {
    href: "",
    download: "",
    click: () => {
      clicked = true;
    },
  } as unknown as HTMLAnchorElement;

  downloadScorecardCsv(buildExportModel(sampleGame()), {
    createObjectURL: (blob) => {
      captured.blob = blob;
      return "blob:scorecard";
    },
    revokeObjectURL: (url) => {
      revokedUrl = url;
    },
    createAnchor: () => anchor,
  });

  const createdBlob = captured.blob;
  assert.ok(createdBlob);
  assert.match(await createdBlob.text(), /"Hole","Player 1"/);
  assert.equal(anchor.href, "blob:scorecard");
  assert.equal(anchor.download, "mini-golf-scorecard.csv");
  assert.equal(clicked, true);
  assert.equal(revokedUrl, "blob:scorecard");
});

test("prepares HTML and image exports from the shared calculated model", () => {
  const baseModel = buildExportModel(sampleGame());
  const model = {
    ...baseModel,
    holeTotals: [99, 88, 0],
    playerTotals: [42, 43, 44],
    grandTotal: 129,
  };

  const prepared = prepareScorecardExport(model);
  assert.deepEqual(prepared.scoreRows.map((row) => row.total), [99, 88, 0]);
  assert.deepEqual(prepared.playerTotals, [42, 43, 44]);
  assert.equal(prepared.grandTotal, 129);

  const csv = scorecardToCsv(model);
  assert.match(csv, /"1","2","2","5","99"/);
  assert.match(csv, /"Total","42","43","44","129"/);

  const html = scorecardToHtml(model);
  assert.match(html.html, />99<\/td>/);
  assert.match(html.html, />42<\/td>/);
  assert.match(html.plain, /\t99\n/);

  const image = scorecardToSvg(model);
  assert.match(image.svg, />99<\/text>/);
  assert.match(image.svg, />42<\/text>/);
});

test("escapes player names in every pure export format", () => {
  const game = renamePlayer(sampleGame(), "player-1", "A & <B>");
  const model = buildExportModel(game);

  assert.match(scorecardToCsv(model), /"A & <B>"/);
  assert.match(scorecardToHtml(model).html, /A &amp; &lt;B&gt;/);
  assert.match(scorecardToSvg(model).svg, /A &amp; &lt;B&gt;/);
});

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import vm from "node:vm";
import test from "node:test";
import ts from "typescript";

const require = createRequire(import.meta.url);
const root = new URL("../", import.meta.url).pathname;

// Isolated effect dispatcher executes the actual hook and storage adapter.
// It deliberately models dependency changes, cleanup and deferred callbacks.
function harness(localStorage) {
  const slots = [], modules = new Map();
  let cursor = 0, dirty = true, effects = [], callbacks = [];
  const react = {
    useState(initial) {
      const id = cursor++;
      if (!(id in slots)) slots[id] = typeof initial === "function" ? initial() : initial;
      return [slots[id], (update) => {
        const next = typeof update === "function" ? update(slots[id]) : update;
        if (!Object.is(next, slots[id])) { slots[id] = next; dirty = true; }
      }];
    },
    useCallback(callback) { return callback; },
    useEffect(effect, deps) {
      const id = cursor++, previous = slots[id];
      if (!previous || deps.some((value, i) => !Object.is(value, previous.deps[i]))) {
        slots[id] = { deps };
        effects.push(() => { previous?.cleanup?.(); slots[id].cleanup = effect(); });
      }
    },
  };
  function load(file) {
    if (modules.has(file)) return modules.get(file);
    const exports = {}; modules.set(file, exports);
    const source = ts.transpileModule(readFileSync(file, "utf8"), {
      compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
    }).outputText;
    vm.runInNewContext(source, { exports, crypto: globalThis.crypto,
      window: { localStorage, setTimeout: (fn) => { callbacks.push(fn); return fn; }, clearTimeout: (fn) => { callbacks = callbacks.filter((item) => item !== fn); } },
      queueMicrotask: (fn) => callbacks.push(fn),
      require: (specifier) => specifier === "react" ? react : specifier.startsWith(".")
        ? load(path.resolve(path.dirname(file), specifier.endsWith(".ts") ? specifier : `${specifier}.ts`)) : require(specifier),
    }, { filename: file });
    return exports;
  }
  const useGame = load(path.join(root, "app/hooks/use-scorecard-game.ts")).useScorecardGame;
  let result;
  return {
    flush() {
      let iterations = 0;
      while (dirty || callbacks.length) {
        assert.ok(++iterations < 30, "hook settles");
        if (dirty) {
          dirty = false; cursor = 0;
          // eslint-disable-next-line react-hooks/rules-of-hooks -- An isolated dispatcher drives this hook regression.
          result = useGame();
          const pending = effects; effects = []; pending.forEach((fn) => fn());
        }
        const pending = callbacks; callbacks = []; pending.forEach((fn) => fn());
      }
      return result;
    },
  };
}

for (const [name, getItem] of [["corrupt", () => "{broken"], ["empty", () => ""], ["denied", () => { throw Error("denied"); }], ["invalid score", () => JSON.stringify({ holes: 1, players: [{ id: "p", name: "Player" }], scores: { p: ["1e2"] } })]]) {
  test(`${name} storage remains untouched through initialisation and score edits`, () => {
    let writes = 0;
    const hook = harness({ getItem, setItem() { writes++; } });
    let state = hook.flush();
    assert.match(state.storageWarning, /not being saved/);
    state.changeScore(state.game.players[0].id, 0, "3");
    state = hook.flush();
    assert.equal(state.game.scores[state.game.players[0].id][0], "3");
    assert.match(state.storageWarning, /not being saved/);
    assert.equal(writes, 0);
  });
}

test("quota failure keeps editing possible and clears only after a successful save", () => {
  let quota = true, raw = null;
  const hook = harness({ getItem: () => raw, setItem(_key, value) { if (quota) throw Error("quota"); raw = value; } });
  let state = hook.flush();
  assert.match(state.storageWarning, /could not be saved/);
  state.changeScore(state.game.players[0].id, 0, "4");
  state = hook.flush();
  assert.equal(state.game.scores[state.game.players[0].id][0], "4");
  assert.match(state.storageWarning, /could not be saved/);
  assert.equal(raw, null);
  quota = false;
  state.changeScore(state.game.players[0].id, 0, "5");
  state = hook.flush();
  assert.equal(state.storageWarning, null);
  const saved = JSON.parse(raw);
  assert.equal(saved.scores[saved.players[0].id][0], "5");
});

import assert from "node:assert/strict";
import test from "node:test";
import { createGame } from "../app/domain/scorecard.ts";
import { loadGame, loadGameState, loadTableTextSize, saveGame, saveTableTextSize } from "../app/scorecard-storage.ts";

test("denied reads retain a usable in-memory round and default text size", () => {
  const storage = { getItem() { throw Error("denied"); }, setItem() { assert.fail("read must not write"); } };
  assert.ok(loadGame(storage).players.length > 0);
  assert.equal(loadGameState(storage).writable, false);
  assert.equal(loadTableTextSize(storage), "medium");
});

test("only absent or valid storage enables automatic saving", () => {
  for (const raw of ["", "{broken", '{"players":[]}']) {
    assert.equal(loadGameState({ getItem: () => raw, setItem() {} }).writable, false);
  }
  assert.equal(loadGameState({ getItem: () => null, setItem() {} }).writable, true);
  const game = createGame();
  assert.deepEqual(loadGameState({ getItem: () => JSON.stringify(game), setItem() {} }), { game, writable: true });
});

test("saving reports denied storage and quota errors instead of claiming success", () => {
  const game = createGame();
  assert.equal(saveGame(game, null), false);
  const full = { getItem: () => null, setItem() { throw Error("quota"); } };
  assert.equal(saveGame(game, full), false);
  assert.doesNotThrow(() => saveTableTextSize("large", full));
  let saved = "";
  assert.equal(saveGame(game, { getItem: () => null, setItem: (_key, value) => { saved = value; } }), true);
  assert.deepEqual(JSON.parse(saved), game);
});

